function save(){try{localStorage.setItem('aariaPrivateKitchenV4',JSON.stringify(state))}catch{}}function exportStandaloneWithProgress(){try{const payload=JSON.stringify({id:'snapshot-'+Date.now()+'-'+Math.random().toString(36).slice(2),snapshot:state}).replace(/</g,'\\u003c');let html='<!doctype html>\n'+document.documentElement.outerHTML;const marker=/<script id="aaria-embedded-snapshot" type="application\/json">[\s\S]*?\x3c\/script>/;if(!marker.test(html))throw new Error('Snapshot container missing');const replacement='<script id="aaria-embedded-snapshot" type="application/json">'+payload+'<'+'/script>';html=html.replace(marker,replacement);const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Aarias_Magical_Kitchen_Offline.html';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notice('Standalone HTML saved with this device’s planner and progress ✨')}catch{notice('Could not save the standalone copy. Please try again on this device.')}}function monday(d){let n=new Date(d.getFullYear(),d.getMonth(),d.getDate());n.setDate(n.getDate()-(n.getDay()+6)%7);return n}function key(){let d=monday(new Date());d.setDate(d.getDate()+weekOffset*7);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}function createWeek(){let arr=shuffle(RECIPES),picked=[];for(let test of [r=>r.category==='Indian',r=>r.method.includes('Air fryer'),r=>r.method.includes('Stovetop'),r=>r.method.includes('No cooking')]){let r=arr.find(x=>test(x)&&!picked.includes(x.id));if(r)picked.push(r.id)}for(let r of arr){if(picked.length===7)break;if(!picked.includes(r.id))picked.push(r.id)}return {ids:shuffle(picked),locks:[false,false,false,false,false,false,false]}}function getWeek(){let k=key();if(!state.weeks[k]){state.weeks[k]=createWeek();save()}return state.weeks[k]};function find(id){return RECIPES.find(r=>r.id===Number(id))||RECIPES[0]};function notice(s){let el=$('#toast');el.textContent=translateText(s);el.classList.remove('hidden');clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.classList.add('hidden'),2400)}
function chirp(notes=[660,880,1047]){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();let t=audioCtx.currentTime;notes.forEach((n,i)=>{let osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.setValueAtTime(n,t+i*.15);gain.gain.setValueAtTime(.0001,t+i*.15);gain.gain.exponentialRampToValueAtTime(.045,t+i*.15+.02);gain.gain.exponentialRampToValueAtTime(.0001,t+i*.15+.35);osc.connect(gain).connect(audioCtx.destination);osc.start(t+i*.15);osc.stop(t+i*.15+.38)})}catch{}}
function music(toggle){if(toggle===false||musicOn){musicOn=false;clearInterval(musicTimer);musicTimer=null;notice('Fairy music paused 🎵')}else{musicOn=true;chirp([523,659,784,1047]);let seq=[[523,659,784],[587,740,880],[659,784,988],[587,698,880]];let n=0;musicTimer=setInterval(()=>{if(document.hidden)return;chirp(seq[n++%seq.length])},2500);notice('Fairy music playing ✨')}render()}
function say(t){if(!('speechSynthesis'in window)){notice('Read-aloud is not available on this device');return}window.speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(translateText(t));u.rate=.87;u.pitch=1.12;u.lang=state.language;const voice=window.speechSynthesis.getVoices().find(v=>v.lang===state.language);if(voice)u.voice=voice;window.speechSynthesis.speak(u)}function burst(){let el=$('#confetti');el.innerHTML='';for(let i=0;i<38;i++){let p=document.createElement('i');p.textContent=['⭐','✨','💖','🌸','🦄'][i%5];p.style.left=(Math.random()*100)+'%';p.style.animationDelay=(Math.random()*.7)+'s';el.append(p)}setTimeout(()=>el.innerHTML='',3300)}
function goto(v){view=v;const route='#aria/'+v+(v==='recipe'&&selected?'/'+selected.id+'/'+step:'');if(location.hash!==route)location.hash=route;else render();window.scrollTo(0,0)}function openRecipe(id){selected=find(id);step=0;goto('recipe')}function header(title){return `<div class="topbar"><div><div class="eyebrow">Made just for Aaria ✨</div><h2>${title}</h2></div>${avatar('')}</div>`}
