function recipeAvatarIndex(id){if(Number.isInteger(state.avatarAssignments[id])&&state.avatarAssignments[id]>=0&&state.avatarAssignments[id]<AARIA_AVATARS.length&&(id===3||state.avatarAssignments[id]!==3)&&state.avatarAssignments[id]!==state.avatarAssignments[id-1])return state.avatarAssignments[id];let pool=Array.from({length:AARIA_AVATARS.length},(_,i)=>i).filter(i=>id===3||i!==3),previous=state.avatarAssignments[id-1];if(pool.length>1)pool=pool.filter(i=>i!==previous);const chosen=pool[Math.floor(Math.random()*pool.length)];state.avatarAssignments[id]=chosen;save();return chosen;}
// Assign all recipe cards once so neighboring recipes receive varied identities.
RECIPES.forEach(r=>recipeAvatarIndex(r.id));
