function batchDishImage(r){if(NEW_RECIPE_ART[r.id]?.hero)return `<figure class="ref-dish new-recipe-hero-art"><img src="${NEW_RECIPE_ART[r.id].hero}" alt="${safe(NEW_RECIPE_ART[r.id].heroAlt)}"><span>Aaria is Head Chef</span></figure>`;if(NEW_RECIPE_ART[r.id])return `<figure class="ref-dish new-recipe-art-pending"><span>${safe(r.emoji)} Artwork review pending</span></figure>`;if(BATCH_ATLASES[r.id])return atlasImage(r,0,'ref-dish','Finished '+r.title);return `<div class="ref-dish"><img class="ref-dish-photo" src="${INLINE_DISH_PHOTOS[r.id]}" alt="Finished ${safe(r.title)} on a plate"><span>🍽️ The finished roll-ups</span></div>`;}

