Object.assign(PT_TRANSLATIONS,{"Family recipe ideas":"Ideias de receitas para a família","Friend-friendly recipe ideas":"Ideias de receitas para amigos","Pick a recipe to make with Mommy or Daddy. You can open any card below to start cooking together.":"Escolha uma receita para fazer com a mamãe ou o papai. Toque em um cartão para começar.","Choose an easy recipe to make together. Ask a grown-up to help with hot appliances and sharp tools.":"Escolha uma receita fácil para preparar juntos. Peça ajuda a um adulto com aparelhos quentes e utensílios afiados.","Spin to choose a recipe!":"Gire para escolher uma receita!","Spin for your magical week!":"Gire para montar sua semana mágica!","The wheel will pick from Aaria’s recipe book. 🎵 Music plays while it spins.":"A roleta vai escolher do livro de receitas da Aaria. 🎵 A música toca enquanto ela gira.","Ready when you are, Chef!":"Pronta quando você estiver, chef!","Spin the wheel!":"Girar a roleta!","Back home":"Voltar ao início"});
const PT_RECIPES={"1":{"title":"Cestinhas de pão com ovo e queijo","steps":["Achate as fatias de pão e coloque cada uma em uma forminha de silicone própria para air fryer.","Bata os ovos, o leite, o queijo e uma pitada de sal em uma tigela.","Despeje a mistura nas cestinhas de pão, deixando espaço no topo.","Asse na air fryer a 160°C por 8–12 minutos, até o ovo ficar completamente firme. Deixe esfriar antes de comer."],"ingredients":["4 fatias de pão de forma macio","2 ovos","4 colheres de sopa de muçarela ou cheddar ralado","2 colheres de sopa de leite","Um pouco de manteiga","Uma pitada de sal"]},"2":{"title":"Mini sanduíches de nuggets","steps":["Prepare os nuggets completamente, seguindo as instruções da embalagem.","Abra os pãezinhos. Passe um pouco de ketchup, se quiser.","Coloque 1–2 nuggets já preparados em cada pão e acrescente queijo.","Aqueça os sanduíches na air fryer a 160°C por 4–7 minutos, até o queijo derreter e tudo ficar quente. Acrescente a alface depois."],"ingredients":["4 pãezinhos para mini-hambúrguer","4–8 nuggets de frango já completamente preparados","½ xícara de muçarela ou cheddar ralado","1–2 colheres de sopa de ketchup (opcional)","Alface ou fatias finas de tomate (opcional)"]},"3":{"title":"Rolinhos de banana com chocolate","steps":["Achate cada fatia de pão com um rolo de massa ou com as mãos.","Passe uma camada fina de creme de chocolate em cada fatia.","Descasque a banana, quebre em pedaços pequenos e coloque perto de uma das bordas.","Enrole bem firme; pincele levemente com manteiga, se usar.","Asse na air fryer a 170°C por 5–7 minutos, até dourar levemente. Deixe os rolinhos esfriarem bem; o recheio de chocolate pode estar quente."],"ingredients":["4 fatias de pão de forma macio","1 banana madura","3–4 colheres de sopa de creme de chocolate","1 colher de chá de manteiga derretida (opcional)","Canela (opcional)"]},"4":{"title":"Bolinhas de batata com queijo","steps":["Misture a batata amassada já fria com o queijo ralado e o milho opcional.","Com as mãos limpas, modele bolinhas e passe na farinha de rosca.","Pincele levemente com azeite, se quiser. Distribua em uma única camada.","Asse na air fryer a 180°C por 8–12 minutos, virando uma vez, até dourar e aquecer por inteiro. Deixe esfriar antes de comer."],"ingredients":["1 xícara de batata cozida, fria e amassada","½ xícara de queijo ralado","⅓ xícara de farinha de rosca","1 colher de sopa de milho (opcional)","1 colher de chá de azeite (opcional)"]},"5":{"title":"Cestinhas de minipizza de pão","steps":["Achate o pão e coloque nas forminhas de silicone.","Passe 1 colher de sopa de molho de tomate em cada cestinha.","Acrescente milho, pimentão em cubinhos e queijo.","Asse na air fryer a 170°C por 5–8 minutos, até o pão ficar crocante e o queijo derreter. Deixe esfriar."],"ingredients":["4 fatias de pão de forma","4 colheres de sopa de molho de tomate para pizza","½ xícara de muçarela ralada","2 colheres de sopa de milho","2 colheres de sopa de pimentão em cubinhos"]},"6":{"title":"Espirais de queijo e milho","steps":["Abra a massa folhada gelada sobre uma superfície limpa.","Passe uma camada fina de molho de tomate, se usar; espalhe queijo e milho bem escorrido.","Enrole formando um cilindro firme. Corte em 8–10 fatias.","Coloque as fatias deitadas, com espaço entre elas. Asse na air fryer a 170°C por 9–13 minutos, até crescer, dourar e cozinhar a massa por completo. Deixe esfriar."],"ingredients":["1 folha de massa folhada pronta (cerca de 250 g)","½ xícara de queijo ralado","¼ xícara de milho escorrido","1 colher de sopa de molho de tomate (opcional)"]},"7":{"title":"Muffins coloridos de legumes e queijo","steps":["Lave os legumes e rale a cenoura.","Bata os ovos com o leite e o sal; misture o queijo, a cenoura e o milho.","Despeje em forminhas pequenas de silicone, deixando um pouco de espaço no topo.","Asse na air fryer a 160°C por 10–14 minutos, até crescer e ficar completamente firme no centro. Deixe esfriar."],"ingredients":["2 ovos","3 colheres de sopa de queijo ralado","2 colheres de sopa de cenoura ralada","2 colheres de sopa de milho","1 colher de sopa de leite","Uma pitada de sal"]},"8":{"title":"Nuggets de brócolis e queijo","steps":["Cozinhe o brócolis, deixe esfriar e pique bem pequeno.","Misture o brócolis, o queijo, o ovo, a farinha de rosca e o tempero opcional.","Com as mãos limpas, modele nuggets pequenos e levemente achatados.","Asse na air fryer a 180°C por 10–14 minutos, virando na metade do tempo, até dourar, firmar e cozinhar por completo. Deixe esfriar."],"ingredients":["1 xícara de brócolis cozido, frio e bem picadinho","½ xícara de queijo ralado","1 ovo","⅓ xícara de farinha de rosca","Uma pitada de sal e pimenta-do-reino (opcional)"]},"9":{"title":"Minipizzas arco-íris de legumes","steps":["Coloque as fatias de pão sobre uma tábua limpa.","Passe cerca de 1 colher de sopa de molho de tomate em cada fatia.","Decore com pimentão em cubinhos e milho; polvilhe queijo e orégano.","Asse na air fryer a 170°C por 5–7 minutos, até o queijo derreter e o pão ficar crocante. Deixe esfriar."],"ingredients":["4 fatias pequenas de pão","4 colheres de sopa de molho de tomate para pizza","½ xícara de muçarela","¼ xícara de pimentão em cubinhos bem pequenos","¼ xícara de milho","Orégano (opcional)"]},"10":{"title":"Batata-doce divertida em gomos","steps":["Lave a batata-doce e corte em gomos finos, mais fáceis que esculpir carinhas.","Seque bem e misture os gomos com azeite, sal e páprica opcional.","Distribua em uma única camada no cesto da air fryer.","Asse a 190°C por 12–18 minutos, virando na metade do tempo, até ficar macia por dentro e dourada por fora."],"ingredients":["1 batata-doce média","1 colher de chá de azeite","Uma pitada de sal","¼ colher de chá de páprica (opcional)"]},"11":{"title":"Rolinhos arco-íris de legumes","steps":["Lave bem todos os legumes. Corte o pepino.","Passe cream cheese em cada tortilha.","Acrescente alface, cenoura ralada, pepino e tomate opcional em uma camada fina.","Enrole cada tortilha bem firme. Corte em espirais pequenas, fáceis de comer."],"ingredients":["2 tortilhas integrais","3 colheres de sopa de cream cheese","½ xícara de cenoura ralada","½ pepino cortado em palitos finos","2 folhas de alface","Fatias de tomate (opcional)"]},"12":{"title":"Panquequinhas de milho com queijo","steps":["Misture milho, ovo, farinha, queijo e leite até formar uma massa grossa que possa ser colocada com uma colher.","Aqueça uma frigideira antiaderente com um pouco de azeite em fogo médio-baixo.","Coloque pequenas colheradas e cozinhe por cerca de 2–3 minutos de cada lado.","Confira se o centro está completamente cozido e dourado. Deixe esfriar antes de comer."],"ingredients":["½ xícara de milho","1 ovo","3 colheres de sopa de farinha de trigo integral","2 colheres de sopa de queijo ralado","2 colheres de sopa de leite","1 colher de chá de azeite para a frigideira"]},"13":{"title":"Torradinhas de queijo em forma de ursinho","steps":["Coloque o queijo sobre o pão.","Toste até o queijo derreter.","Deixe esfriar um pouco; acrescente rodelas de pepino como orelhas e tomates cortados ao meio como focinhos."],"ingredients":["2 fatias de pão","2 fatias de queijo","4 rodelas de pepino","2 tomates-cereja"]},"14":{"title":"Minipizzas de bagel","steps":["Passe molho nas metades dos bagels.","Acrescente milho, pimentão e queijo.","Asse na air fryer até o queijo derreter; deixe esfriar."],"ingredients":["2 minibagels cortados ao meio","4 colheres de sopa de molho de tomate","½ xícara de muçarela","2 colheres de sopa de milho","2 colheres de sopa de pimentão em cubinhos"]},"15":{"title":"Palitinhos crocantes de abobrinha","steps":["Corte a abobrinha em palitos.","Passe no ovo batido e depois na farinha de rosca misturada com parmesão.","Asse na air fryer em uma única camada, até dourar e a abobrinha ficar macia."],"ingredients":["1 abobrinha pequena","1 ovo","⅓ xícara de farinha de rosca","2 colheres de sopa de parmesão","1 colher de chá de azeite"]},"16":{"title":"Quesadillas arco-íris com queijo","steps":["Espalhe queijo e legumes sobre metade de cada tortilha.","Dobre e pressione levemente.","Asse na air fryer até ficar crocante e o queijo derreter."],"ingredients":["2 tortilhas pequenas","½ xícara de muçarela","¼ xícara de milho","¼ xícara de pimentão em cubinhos bem pequenos"]},"17":{"title":"Panquecas de banana com carinhas","steps":["Amasse a banana; misture o ovo e a aveia.","Prepare panquecas pequenas em uma frigideira levemente untada, até ficarem completamente firmes.","Decore as panquecas já frias com morangos cortados."],"ingredients":["1 banana madura","1 ovo","⅓ xícara de aveia em flocos","3 morangos"]},"18":{"title":"Varinhas arco-íris de frutas","steps":["Lave as frutas, descasque e corte em pedaços pequenos.","Organize as cores como um arco-íris em um prato ou em palitos próprios para alimentos, sem ponta."],"ingredients":["4 morangos","1 banana","1 kiwi","½ manga","¼ xícara de mirtilos"]},"19":{"title":"Rosquinhas de maçã com canela","steps":["Retire o miolo das maçãs e corte em rodelas grossas.","Pincele levemente com manteiga e polvilhe canela.","Asse na air fryer até ficar macio; deixe esfriar."],"ingredients":["2 maçãs","½ colher de chá de canela","1 colher de chá de manteiga derretida"]},"20":{"title":"Picolés de morango com iogurte","steps":["Lave os morangos; bata as frutas com o iogurte.","Despeje em forminhas de picolé e congele até ficar firme."],"ingredients":["1 xícara de iogurte natural","½ xícara de morangos","1 banana madura"]},"21":{"title":"Jardim de flores de legumes","steps":["Lave e fatie os legumes, cortando os tomates em quatro partes.","Passe cream cheese nos biscoitos.","Organize os pedaços de legumes como flores e folhas."],"ingredients":["½ pepino","1 cenoura","4 tomates-cereja","2 colheres de sopa de cream cheese","6 biscoitos integrais"]},"22":{"title":"Bolinhos de couve-flor com queijo","steps":["Cozinhe a couve-flor e deixe esfriar.","Misture todos os ingredientes e modele bolinhos pequenos.","Asse na air fryer até ficar firme, dourar e o ovo cozinhar completamente."],"ingredients":["1 xícara de couve-flor cozida e picada","1 ovo","⅓ xícara de farinha de rosca","½ xícara de queijo ralado"]},"23":{"title":"Bolinhas de arroz arco-íris","steps":["Com as mãos limpas, misture o arroz recém-cozido, morno e não quente, com os legumes já cozidos.","Modele bolinhas pequenas e coma logo após o preparo."],"ingredients":["1 xícara de arroz glutinoso recém-cozido e já resfriado","¼ xícara de ervilhas cozidas","¼ xícara de cenoura cozida em cubinhos","2 colheres de sopa de milho cozido","2 colheres de sopa de queijo ralado"]},"24":{"title":"Tesourinhos crocantes de grão-de-bico","steps":["Escorra o grão-de-bico e seque bem.","Misture com azeite e páprica.","Asse na air fryer até ficar crocante; deixe esfriar e confira a textura antes de comer."],"ingredients":["1 xícara de grão-de-bico cozido e escorrido","1 colher de chá de azeite","¼ colher de chá de páprica suave"]},"25":{"title":"Pastelinhos de frango com queijo","steps":["Corte a massa folhada em quadrados.","Acrescente frango, queijo e molho; dobre e pressione as bordas.","Asse na air fryer até a massa dourar e cozinhar por completo e o recheio ficar quente."],"ingredients":["1 folha de massa folhada pronta","½ xícara de frango completamente cozido e desfiado","⅓ xícara de queijo","1 colher de sopa de molho de tomate"]},"26":{"title":"Bocadinhos de pizza com nuggets","steps":["Prepare os nuggets completamente, seguindo a embalagem.","Passe molho no pão; acrescente nuggets picados, milho e queijo.","Asse na air fryer até aquecer e o queijo derreter."],"ingredients":["4 fatias pequenas de pão","4 nuggets de frango completamente preparados","4 colheres de sopa de molho de tomate","½ xícara de muçarela","2 colheres de sopa de milho"]},"27":{"title":"Nuggets de frango e cenoura","steps":["Reserve o manuseio do frango cru para um adulto.","Misture os ingredientes com utensílios limpos; modele nuggets pequenos e achatados.","Asse na air fryer até o centro atingir 74°C, conferindo com um termômetro."],"ingredients":["250 g de frango moído","½ xícara de cenoura bem ralada","1 ovo","⅓ xícara de farinha de rosca","Uma pitada de sal"]},"28":{"title":"Ninhos de ovo no pão","steps":["Achate o pão e coloque em quatro forminhas de silicone.","Bata os ovos e misture o queijo e o milho.","Encha as forminhas; asse na air fryer até os ovos ficarem completamente firmes."],"ingredients":["4 fatias de pão","2 ovos","¼ xícara de muçarela","2 colheres de sopa de milho"]},"29":{"title":"Bocadinhos de omelete arco-íris","steps":["Bata os ovos; misture o queijo e os legumes bem picadinhos.","Despeje em forminhas de silicone.","Cozinhe até o centro ficar completamente firme."],"ingredients":["2 ovos","¼ xícara de queijo ralado","2 colheres de sopa de cenoura ralada","2 colheres de sopa de espinafre picado","2 colheres de sopa de pimentão em cubinhos"]},"30":{"title":"Sanduíches de ovo em forma de estrela","steps":["Prepare ovos mexidos na frigideira, cozinhando completamente.","Coloque os ovos e o queijo entre as fatias de pão.","Use um cortador em forma de estrela; sirva morno."],"ingredients":["2 fatias de pão","2 ovos","2 colheres de sopa de queijo ralado","1 colher de chá de manteiga"]},"31":{"title":"Sushi de morango e banana","steps":["Passe cream cheese nas tortilhas.","Coloque banana e morangos fatiados; enrole bem firme.","Corte em espirais pequenas."],"ingredients":["2 tortilhas pequenas","1 banana","4 morangos","3 colheres de sopa de cream cheese"]},"32":{"title":"Espirais de maçã com canela","steps":["Pique a maçã em cubinhos bem pequenos.","Espalhe maçã e canela sobre a massa folhada; enrole formando um cilindro.","Corte em fatias e asse na air fryer até a massa cozinhar por completo."],"ingredients":["1 folha de massa folhada","1 maçã pequena","½ colher de chá de canela","1 colher de chá de açúcar (opcional)"]},"33":{"title":"Taças de frutas arco-íris","steps":["Lave as frutas e corte em pedaços.","Faça camadas de iogurte, frutas e aveia em copos transparentes.","Coma imediatamente ou mantenha na geladeira."],"ingredients":["1 xícara de iogurte natural","½ xícara de manga picada","½ banana","4 morangos","2 colheres de sopa de aveia"]},"34":{"title":"Bolinhos de cenoura e batata","steps":["Misture a batata cozida já fria com cenoura ralada, queijo e farinha de rosca.","Modele bolinhos pequenos.","Asse na air fryer até dourar e aquecer por inteiro."],"ingredients":["1 xícara de batata cozida e amassada","½ xícara de cenoura ralada","¼ xícara de queijo","⅓ xícara de farinha de rosca"]},"35":{"title":"Triângulos arco-íris de legumes","steps":["Recheie metade de cada tortilha com queijo, milho e espinafre.","Dobre e pressione.","Asse na air fryer até ficar crocante e o queijo derreter."],"ingredients":["2 tortilhas","½ xícara de queijo","¼ xícara de milho cozido","¼ xícara de espinafre picado"]},"36":{"title":"Barquinhos de minipimentão arco-íris","steps":["Corte os pimentões ao meio e retire as sementes.","Recheie com arroz recém-cozido, milho e queijo.","Asse na air fryer até os pimentões ficarem macios e o recheio aquecer."],"ingredients":["4 minipimentões doces","½ xícara de arroz cozido","¼ xícara de milho cozido","¼ xícara de queijo ralado"]},"37":{"title":"Espirais arco-íris de frango","steps":["Lave os legumes.","Passe cream cheese e acrescente frango cozido, cenoura e alface.","Enrole bem firme, corte em fatias e sirva logo após o preparo."],"ingredients":["2 tortilhas","½ xícara de frango completamente cozido e resfriado","3 colheres de sopa de cream cheese","¼ xícara de cenoura ralada","2 folhas de alface"]},"38":{"title":"Nuvens de ovo com espinafre e queijo","steps":["Bata os ovos com o leite; acrescente espinafre e queijo.","Despeje em forminhas de silicone.","Asse na air fryer até ficar completamente firme."],"ingredients":["2 ovos","¼ xícara de muçarela","¼ xícara de espinafre bem picadinho","1 colher de sopa de leite"]},"39":{"title":"Minipanquecas de frango e milho","steps":["Misture todos os ingredientes até formar uma massa grossa.","Prepare pequenas colheradas em uma frigideira levemente untada, até o centro cozinhar completamente."],"ingredients":["½ xícara de frango completamente cozido e desfiado","¼ xícara de milho","1 ovo","¼ xícara de farinha de trigo","2 colheres de sopa de leite"]},"40":{"title":"Sanduichinhos sorridentes de maçã","steps":["Retire o miolo da maçã e corte em fatias finas.","Passe pasta de sementes ou de amendoim, se for adequada às suas alergias.","Acrescente sorrisos de banana e sirva."],"ingredients":["1 maçã","2 colheres de sopa de pasta de amendoim ou de sementes de girassol","½ banana"]},"41":{"title":"Almôndegas de frango com queijo","steps":["Reserve o manuseio do frango cru para um adulto.","Misture e modele almôndegas pequenas com utensílios limpos.","Asse na air fryer até o centro atingir 74°C, conferindo com um termômetro culinário."],"ingredients":["250 g de frango moído","¼ xícara de queijo","¼ xícara de farinha de rosca","1 ovo"]},"42":{"title":"Rolinhos de rabanada com morango","steps":["Achate o pão.","Corte os morangos, coloque dentro do pão e enrole.","Mergulhe rapidamente no ovo batido com leite.","Asse na air fryer até o pão dourar e a camada de ovo cozinhar completamente."],"ingredients":["4 fatias de pão","4 morangos","1 ovo","2 colheres de sopa de leite","Uma pitada de canela"]},"43":{"title":"Estrelinhas de brócolis e batata","steps":["Misture batata já fria, brócolis, queijo e farinha de rosca.","Modele estrelinhas ou bolinhos achatados.","Asse na air fryer até dourar e aquecer por inteiro."],"ingredients":["1 xícara de batata cozida e amassada","½ xícara de brócolis cozido e picado","¼ xícara de queijo","⅓ xícara de farinha de rosca"]},"44":{"title":"Muffins de ovo com sabor de pizza","steps":["Bata os ovos e misture legumes, queijo e orégano.","Encha as forminhas de silicone.","Cozinhe até o centro ficar completamente firme."],"ingredients":["2 ovos","¼ xícara de muçarela","2 colheres de sopa de tomate em cubinhos bem pequenos","2 colheres de sopa de pimentão em cubinhos","Uma pitada de orégano"]},"45":{"title":"Biscoitinhos de banana e aveia","steps":["Amasse a banana e misture com aveia e canela.","Modele biscoitinhos achatados e acrescente gotas de chocolate, se quiser.","Asse na air fryer até firmar e dourar levemente."],"ingredients":["1 banana madura","¾ xícara de aveia em flocos","¼ colher de chá de canela","1 colher de sopa de gotas de chocolate (opcional)"]},"46":{"title":"Pastelinhos de nuggets","steps":["Prepare os nuggets seguindo a embalagem e pique.","Acrescente nuggets, molho e queijo às metades das tortilhas.","Dobre e asse na air fryer até aquecer e ficar crocante."],"ingredients":["2 tortilhas","4 nuggets completamente preparados","¼ xícara de muçarela","2 colheres de sopa de molho de tomate"]},"47":{"title":"Vitamina de manga ensolarada","steps":["Lave e prepare as frutas.","Bata tudo no liquidificador até ficar cremoso.","Despeje nos copos e saboreie gelado."],"ingredients":["½ xícara de manga picada","1 banana","½ xícara de iogurte natural","½ xícara de leite"]},"48":{"title":"Bolinhos de cenoura com queijo","steps":["Misture cenoura, ovo, farinha e queijo.","Prepare pequenas colheradas em uma frigideira antiaderente levemente untada, até dourar e cozinhar completamente."],"ingredients":["1 xícara de cenoura ralada","1 ovo","¼ xícara de farinha de trigo","¼ xícara de queijo ralado"]},"49":{"title":"Copinhos crocantes de morango e banana","steps":["Lave as frutas e corte em fatias.","Faça camadas de iogurte, banana, morango e granola nos copos.","Coma enquanto ainda estiver crocante."],"ingredients":["½ xícara de morangos","1 banana","1 xícara de iogurte","¼ xícara de granola"]},"50":{"title":"Pizzas de frango estreladas da Aaria","steps":["Corte o pão em estrelas, se quiser.","Passe molho e acrescente frango cozido, milho e queijo.","Asse na air fryer até aquecer e o queijo derreter."],"ingredients":["4 fatias de pão","½ xícara de frango completamente cozido e desfiado","4 colheres de sopa de molho de tomate","½ xícara de queijo","2 colheres de sopa de milho"]},"51":{"title":"Torrada de queijo com masala","steps":["Espalhe queijo, legumes em cubinhos bem pequenos e uma pitadinha de chaat masala no pão.","Asse na air fryer até o queijo derreter e a torrada ficar crocante."],"ingredients":["2 fatias de pão","½ xícara de queijo ralado","2 colheres de sopa de tomate em cubinhos","2 colheres de sopa de pimentão em cubinhos","Uma pitada de chaat masala"]},"52":{"title":"Cubinhos de paneer tikka","steps":["Corte o paneer e o pimentão.","Envolva no iogurte com tempero suave e azeite.","Asse na air fryer até aquecer por inteiro e dourar levemente."],"ingredients":["150 g de paneer em cubinhos","2 colheres de sopa de iogurte natural","¼ colher de chá de tikka masala suave","½ pimentão","1 colher de chá de azeite"]},"53":{"title":"Sanduíche de batata com queijo","steps":["Misture batata cozida, queijo e cominho.","Coloque entre as fatias de pão.","Toste em uma frigideira levemente untada com manteiga, até dourar dos dois lados."],"ingredients":["2 fatias de pão","½ xícara de batata cozida e amassada","¼ xícara de queijo","Uma pitada de cominho","1 colher de chá de manteiga"]},"54":{"title":"Bocadinhos de pizza com paneer","steps":["Passe molho no pão.","Acrescente paneer, milho e muçarela.","Asse na air fryer até aquecer e o queijo derreter."],"ingredients":["4 fatias pequenas de pão","½ xícara de paneer em cubinhos","¼ xícara de muçarela","4 colheres de sopa de molho de tomate","2 colheres de sopa de milho"]},"55":{"title":"Mini aloo tikki","steps":["Misture batata, ervilha, farinha de rosca e cominho.","Modele bolinhos pequenos e achatados.","Prepare na frigideira com um pouco de azeite, até ficar crocante e quente por inteiro."],"ingredients":["1 xícara de batata cozida e amassada","¼ xícara de ervilhas cozidas","¼ xícara de farinha de rosca","Uma pitada de cominho moído","1 colher de chá de azeite"]},"56":{"title":"Rolinhos crocantes de pão com batata","steps":["Misture batata, ervilha e cominho.","Achate o pão levemente, acrescente o recheio e enrole bem firme, umedecendo as bordas.","Pincele azeite e asse na air fryer até ficar crocante."],"ingredients":["4 fatias de pão","¾ xícara de batata cozida e amassada","¼ xícara de ervilhas cozidas","Uma pitada de cominho","1 colher de chá de azeite"]},"57":{"title":"Bolinhos arco-íris de legumes","steps":["Misture os legumes cozidos já frios com batata e farinha de rosca.","Modele corações ou estrelas.","Asse na air fryer até dourar e aquecer por inteiro."],"ingredients":["1 xícara de batata cozida e amassada","¼ xícara de cenoura cozida","¼ xícara de ervilhas cozidas","2 colheres de sopa de milho","⅓ xícara de farinha de rosca"]},"58":{"title":"Mini besan chilla","steps":["Bata farinha de grão-de-bico, água e sal até formar uma massa fluida; misture cenoura e coentro.","Prepare panquecas pequenas e finas, cozinhando dos dois lados por completo."],"ingredients":["½ xícara de besan (farinha de grão-de-bico)","½ xícara de água (ajuste conforme necessário)","¼ xícara de cenoura ralada","1 colher de sopa de coentro picado","Uma pitada de sal"]},"59":{"title":"Mini suji uttapam","steps":["Misture semolina, iogurte e água; deixe descansar por 10 minutos.","Acrescente cenoura, tomate e bicarbonato de sódio.","Prepare panquecas pequenas e grossas, tampadas e em fogo baixo a médio, virando até cozinhar por completo."],"ingredients":["½ xícara de semolina (suji)","¼ xícara de iogurte natural","¼ xícara de água (ajuste conforme necessário)","2 colheres de sopa de cenoura ralada","2 colheres de sopa de tomate em cubinhos","¼ colher de chá de bicarbonato de sódio"]},"60":{"title":"Ovos mexidos com queijo e especiarias","steps":["Refogue cebola e tomate na frigideira com azeite até amaciar.","Acrescente ovos batidos e cúrcuma; mexa até os ovos cozinharem completamente.","Acrescente o queijo e deixe derreter."],"ingredients":["2 ovos","2 colheres de sopa de tomate em cubinhos","2 colheres de sopa de cebola bem picadinha","¼ xícara de queijo","Uma pitada de cúrcuma","1 colher de chá de azeite"]},"61":{"title":"Minipanquecas de banana malpua","steps":["Amasse a banana; bata com farinha, leite e cardamomo até formar uma massa grossa.","Prepare panquecas pequenas em uma frigideira levemente untada, até cozinhar completamente."],"ingredients":["1 banana madura","½ xícara de farinha de trigo","⅓ xícara de leite (ajuste conforme necessário)","Uma pitada de cardamomo","1 colher de chá de azeite"]},"62":{"title":"Poha arco-íris de legumes","steps":["Enxágue o poha rapidamente e escorra.","Cozinhe a cenoura com azeite e um pouco de água até amaciar; acrescente ervilha, cúrcuma e poha.","Aqueça por inteiro e finalize com limão."],"ingredients":["1 xícara de poha grosso","¼ xícara de ervilhas cozidas","¼ xícara de cenoura em cubinhos bem pequenos","¼ colher de chá de cúrcuma","1 colher de chá de azeite","Um gomo de limão"]},"63":{"title":"Ladoo de coco","steps":["Misture coco, leite condensado e cardamomo até formar uma massa que possa ser modelada.","Enrole bolinhas pequenas e leve à geladeira até firmar."],"ingredients":["1 xícara de coco seco ralado fino","⅓ xícara de leite condensado (ajuste conforme necessário)","Uma pitada de cardamomo"]},"64":{"title":"Shrikhand de manga","steps":["Misture iogurte espesso, polpa de manga e cardamomo até ficar cremoso.","Resfrie e sirva em tigelinhas."],"ingredients":["1 xícara de iogurte grego natural espesso","½ xícara de polpa de manga","Uma pitada de cardamomo"]},"65":{"title":"Pizza de roti","steps":["Passe molho nos rotis; acrescente pimentão, milho e queijo.","Aqueça em uma frigideira antiaderente tampada, em fogo baixo, até o queijo derreter e a base ficar crocante."],"ingredients":["2 rotis prontos","4 colheres de sopa de molho de tomate","½ xícara de muçarela","¼ xícara de pimentão em cubinhos","2 colheres de sopa de milho"]}};












/* Aaria 2.0 recipe merge: IDs 66–95; protected IDs 1–65 are unchanged. */
Object.assign(PT_RECIPES,{"66":{"title":"Lasanha arco-íris de legumes","steps":["Coloque a farinha em uma tigela. Quebre os ovos e acrescente a água medida. Misture e sove até formar uma massa lisa. Lave as mãos depois de tocar nos ovos crus.","Polvilhe um pouco de farinha na bancada e abra a massa em folhas finas com um rolo de madeira. Corte tiras largas usando um cortador de massa sem ponta afiada.","Espalhe um pouco de molho de tomate na travessa. Faça camadas de massa, abobrinha, cenoura e muçarela; repita e finalize com molho e queijo.","Um adulto coloca a travessa no forno preaquecido a 180°C e assa até a massa ficar macia e o centro bem quente, cerca de 25–30 minutos. Um adulto retira; deixe esfriar antes de servir."],"ingredients":["250 g de farinha de trigo branca","2 ovos médios (100 g de parte comestível)","30 g de água para a massa","180 g de molho de tomate simples","150 g de abobrinha crua em fatias finas","100 g de cenoura crua ralada","150 g de muçarela integral ralada","5 g de azeite para untar a travessa","1 g de sal de cozinha"],"category":"Cozinhando com Mamãe e Papai","safety":"Contém trigo/glúten, ovo e leite. Um adulto cuida do forno quente e da travessa. Lave as mãos e as superfícies depois de tocar em ovo cru; não coma a massa crua.","allergens":["Trigo/glúten","Ovo","Leite"],"crossContact":"Use utensílios limpos e confira os rótulos da massa, do molho e do queijo quanto a alergênicos e avisos de contato cruzado."},"67":{"title":"Paratha de paneer com queijo","steps":["Misture a farinha integral e o sal em uma tigela. Acrescente a água medida aos poucos e sove até obter uma massa macia. Cubra e deixe descansar. Enquanto isso, esfarele o paneer e misture o coentro picado e o cominho.","Divida a massa em quatro bolas iguais e achate cada uma. Coloque um quarto do recheio de paneer em cada uma e feche a massa ao redor do recheio.","Polvilhe um pouco de farinha na bancada. Abra delicadamente cada bola recheada em formato redondo com um rolo de madeira.","Um adulto cozinha cada paratha em uma frigideira quente com um pouco de azeite até os dois lados ficarem cozidos e dourados. O adulto cuida do fogão; deixe os parathas esfriarem antes de servir."],"ingredients":["240 g de farinha de trigo integral","180 g de paneer esfarelado","120 g de água potável para a massa","8 g de folhas frescas de coentro picadas","10 g de azeite para cozinhar na frigideira","1,5 g de sal de cozinha","1 g de cominho em pó"],"category":"Cozinhando com Mamãe e Papai","safety":"Contém trigo/glúten e leite. Um adulto cuida da frigideira quente. Mantenha a massa crua separada do recheio pronto para consumo; lave as mãos depois de tocar na farinha.","allergens":["Trigo/glúten","Leite"],"crossContact":"Confira os rótulos do paneer e da farinha e use utensílios limpos ao cozinhar para alguém com alergia."},"68":{"title":"Mini hambúrgueres de frango","steps":["Lave as mãos. Separe os pãezinhos, a alface lavada e o queijo medido. Um adulto corta o tomate e a cebola com uma faca.","Um adulto modela o frango moído cru com a cebola em quatro hambúrgueres pequenos e cozinha em uma frigideira com pouco azeite. Um termômetro de alimentos deve indicar 74°C no centro. Mantenha separados os utensílios que tocaram no frango cru.","Depois que os hambúrgueres estiverem completamente cozidos, Aaria monta cada sanduíche com hambúrguer, muçarela, alface e tomate no pão.","Coloque os mini hambúrgueres em um prato limpo e sirva depois de esfriarem com segurança. Lave mãos, tábua e utensílios que tocaram no frango cru."],"ingredients":["240 g de frango moído cru","4 pãezinhos simples (100 g no total)","40 g de muçarela integral ralada","20 g de alface crespa lavada","60 g de tomate cru em fatias finas","30 g de cebola crua picada","5 g de azeite para a frigideira","1 g de sal de cozinha"],"category":"Cozinhando com Mamãe e Papai","safety":"Contém trigo/glúten e leite. Frango cru e fogão são tarefas exclusivas de um adulto. Cozinhe o frango até atingir 74°C no centro, usando termômetro de alimentos; lave as mãos e evite contaminação cruzada.","allergens":["Trigo/glúten","Leite"],"crossContact":"Confira os rótulos dos pães e do queijo; mantenha o frango cru separado dos ingredientes prontos para consumo."},"69":{"title":"Biryani de legumes","steps":["Lave o arroz em uma peneira fina até a água sair quase limpa. Escorra enquanto os legumes e temperos medidos são preparados.","Meça as ervilhas, a cenoura e a couve-flor cozidas. Um adulto pica a cebola; Aaria mede o tomate, os temperos e o sal em tigelas.","Um adulto aquece o azeite em uma panela funda, refoga a cebola, acrescenta tomate e temperos e mistura arroz, legumes e água medida. Tampe e cozinhe em fogo baixo até o arroz ficar macio e a água ser absorvida.","Um adulto desliga o fogão e confirma que a panela está segura. Aaria solta o arroz delicadamente com um garfo e serve em tigelas; deixe esfriar antes de comer."],"ingredients":["200 g de arroz branco de grão longo cru","80 g de ervilhas cozidas e escorridas","80 g de cenoura cozida e escorrida","100 g de couve-flor cozida e escorrida","60 g de cebola crua picada","100 g de tomate cru picado","10 g de azeite","2 g de cúrcuma em pó","1 g de cominho em pó","0,5 g de pimenta-do-reino moída","1,5 g de sal de cozinha","450 g de água potável"],"category":"Cozinhando com Mamãe e Papai","safety":"Não contém alergênicos prioritários conhecidos na lista; confira os rótulos dos temperos para avisos de contato cruzado. Um adulto cuida do fogão, do azeite quente e da panela. Mantenha o arroz quente até servir e refrigere as sobras rapidamente.","allergens":[],"crossContact":"Confira os temperos embalados e o arroz quanto a avisos preventivos de alergênicos."},"70":{"title":"Torta de frango com legumes","steps":["Aaria abre a massa folhada em uma bancada limpa e separa quatro forminhas. Um adulto prepara o molho espesso de manteiga, farinha e leite, mistura com o frango cozido e os legumes e deixa o recheio esfriar antes de usar.","Coloque o recheio frio nas bases de massa, cubra cada tortinha com uma tampa de massa e feche as bordas delicadamente com uma ferramenta sem ponta afiada.","Um adulto coloca as tortas no forno preaquecido a 200°C e assa até a massa crescer e dourar e o recheio ficar bem quente. O adulto cuida do forno e das formas quentes.","Um adulto confirma que o recheio está soltando vapor por igual, retira as tortas e deixa esfriar. Aaria ajuda a servir as tortas frias em um prato limpo."],"ingredients":["280 g de massa folhada pronta para assar","200 g de peito de frango assado sem pele, cozido e picado","80 g de ervilhas cozidas e escorridas","80 g de cenoura cozida e escorrida em cubos","40 g de cebola crua picada","120 g de leite integral","15 g de farinha de trigo branca","14,2 g de manteiga sem sal","1 g de sal de cozinha"],"category":"Cozinhando com Mamãe e Papai","safety":"Contém trigo/glúten e leite. Um adulto cuida do forno, das formas quentes e da panela do molho. Se usar frango cozido refrigerado, mantenha-o gelado até usar e reaqueça o recheio até 74°C; não sirva morno.","allergens":["Trigo/glúten","Leite"],"crossContact":"Confira o rótulo da massa folhada: algumas versões contêm ovo ou outros alergênicos. Use utensílios limpos e confira todos os avisos da embalagem."},"71":{"title":"Copinhos de arroz-doce com coco","steps":["Aaria mede o arroz cozido, o leite, o leite condensado, o coco e o sal em uma panela. Com o fogão desligado, ela mistura tudo; um adulto fica ao lado.","Um adulto liga o fogo baixo e permanece junto à panela. Aaria observa de um lado seguro da bancada e avisa quando é hora de mexer; o adulto aquece devagar, mexendo com frequência, até ficar cremoso. Não deixe ferver.","O adulto desliga o fogo e leva a panela para uma superfície segura. Todos esperam até o arroz-doce ficar morno, não quente. Confira se está cremoso e se o arroz está macio; o adulto manuseia a panela quente.","Aaria coloca o arroz-doce já frio em quatro copinhos, com um adulto por perto. Leve à geladeira logo se não for comer imediatamente."],"ingredients":["400 g de arroz branco glutinoso cozido","300 g de leite integral","80 g de leite condensado","18 g de coco seco sem açúcar","0,5 g de sal de cozinha"]},"72":{"title":"Paneer butter masala","steps":["Aaria confere os ingredientes e mede o cominho, a cúrcuma e o sal. Um adulto corta o paneer e a cebola com faca afiada; Aaria pode colocar o paneer em uma tigela e medir o leite.","Um adulto aquece o azeite e a manteiga em uma panela funda em fogo médio-baixo e cozinha a cebola até amaciar. Acrescente os tomates e temperos; o adulto mexe até os tomates amolecerem e formarem um molho.","O adulto acrescenta os cubos de paneer e o leite e cozinha em fogo baixo até o paneer estar bem quente e o molho ficar homogêneo. Aaria fica em um local seguro da bancada e orienta o adulto; o adulto manuseia a panela quente e a colher.","O adulto desliga o fogo e leva a panela para um local resistente ao calor. Sirva porções pequenas com arroz ou roti preparados separadamente; espere esfriar até uma temperatura segura para comer."],"ingredients":["300 g de paneer em cubos de 2 cm","200 g de tomates maduros picados","80 g de cebola picada","10 g de manteiga sem sal","120 g de leite integral","13,5 g de azeite","1 g de cominho em pó","0,5 g de cúrcuma em pó","1 g de sal de cozinha"]},"73":{"title":"Quiche de espinafre e milho","steps":["Aaria desenrola a massa com um adulto por perto e a acomoda delicadamente em uma forma de torta de 20 cm. Um adulto apara a massa e fura a base com um garfo. Mantenha a forma em uma superfície firme.","Aaria bate os ovos com o leite em uma tigela e mistura o milho escorrido e o cheddar ralado. Um adulto pica bem a cebola e o espinafre; acrescente à tigela e misture.","Despeje o recheio na base de massa. Aaria pode ajudar a espalhar o espinafre. Um adulto coloca a forma em uma assadeira e leva ao forno preaquecido.","Um adulto assa a 200°C até a massa dourar e o recheio de ovo ficar completamente firme no centro, cerca de 25–30 minutos. O adulto retira a forma quente e deixa a quiche esfriar antes de cortar."],"ingredients":["250 g de massa folhada pronta","150 g de ovo cru inteiro, sem casca (cerca de 3 ovos grandes)","70 g de espinafre cru lavado e picado","60 g de milho-doce em conserva escorrido","50 g de queijo cheddar ralado","60 g de leite integral","30 g de cebola picada"]},"74":{"title":"Mini samosas de legumes","steps":["Aaria mistura a farinha e o azeite medido em uma tigela; depois acrescenta a água aos poucos e amassa até formar uma massa macia. Cubra a tigela enquanto prepara o recheio.","Amasse a batata já cozida com a ervilha, a cenoura, o cominho, o coentro e o sal. Aaria pode misturar e amassar com um garfo; um adulto confere se os legumes estão frios o bastante para manusear.","Um adulto divide a massa em oito partes e abre cada uma em formato oval pequeno. Aaria coloca uma colherada de recheio no centro; dobre formando um triângulo e pressione bem as bordas. Não coloque recheio demais.","Aaria pincela as samosas levemente com o azeite medido. Um adulto as coloca em uma assadeira forrada e assa a 200°C até dourar e ficar crocante, cerca de 20–25 minutos. O adulto manuseia o forno e a assadeira quentes."],"ingredients":["180 g de farinha de trigo","75 g de água para a massa","20 g de azeite para a massa","220 g de batata cozida sem casca e amassada","80 g de ervilha cozida e escorrida","60 g de cenoura cozida escorrida e picada","1 g de cominho em pó","3 g de folhas de coentro picadas","2 g de sal de cozinha","8 g de azeite para pincelar"]},"75":{"title":"Ravióli de frango e espinafre","steps":["Aaria mistura a farinha e o sal em uma tigela e acrescenta os ovos, a água e o azeite. Mexa e sove até formar uma massa firme. Um adulto ajuda se estiver muito dura; cubra e deixe descansar enquanto prepara o recheio.","Use somente frango já completamente cozido, resfriado e mantido na geladeira. Aaria mistura o frango desfiado com o espinafre e a muçarela. Um adulto confere se não há ossos e pica o espinafre bem fino.","Um adulto abre a massa fina em uma superfície enfarinhada. Aaria coloca pequenas porções de recheio separadas por cerca de 4 cm, cobre com outra folha, pressiona ao redor para tirar o ar e fecha as bordas. Um adulto corta os raviólis com cortador sem ponta.","Um adulto coloca os raviólis em uma panela grande com água em fervura suave e cozinha até a massa ficar macia e o recheio bem quente e soltando vapor. Retire com escumadeira; o adulto manuseia a água fervente. Confira se o centro está quente e espere esfriar antes de servir."],"ingredients":["250 g de farinha de trigo","100 g de ovo cru inteiro, sem casca (cerca de 2 ovos grandes)","50 g de água potável para a massa","120 g de peito de frango assado cozido, desfiado e resfriado","70 g de espinafre cru lavado e picado","60 g de muçarela integral ralada","13,5 g de azeite","2 g de sal de cozinha"]},"76":{"title":"Macarrão de arroz colorido com legumes","steps":["Lave a cenoura e o pimentão. Um adulto cozinha o macarrão, o brócolis e as ervilhas e depois deixa tudo esfriar com segurança.","Com as mãos limpas, coloque o macarrão e os legumes frios em uma tigela grande. Aaria pode usar pegadores infantis para acrescentar os legumes coloridos.","Regue com o azeite medido e salpique o sal medido. Misture delicadamente até distribuir as cores.","Divida o macarrão entre quatro tigelas e confira se tudo está frio antes de comer."],"ingredients":["250 g de macarrão de arroz cozido e frio","80 g de cenoura crua em tiras finas","80 g de pimentão vermelho cru em tiras finas","100 g de brócolis cozido e frio","100 g de ervilhas cozidas e frias","9 g de azeite","1 g de sal fino"]},"77":{"title":"Cupcakes de morango","steps":["Lave e pique os morangos bem pequenos. Reserve alguns pedacinhos para decorar.","Com um adulto, bata a manteiga amolecida com o açúcar até ficar cremoso. Misture os ovos e depois incorpore a farinha, o bicarbonato e o leite. Acrescente os morangos delicadamente.","Coloque a massa por igual em oito forminhas de papel dentro da forma de muffin. Um adulto verifica se o forno está preaquecido a 180°C e assa até o centro firmar.","Um adulto retira a forma quente e deixa os cupcakes esfriarem completamente. Misture o cream cheese com o açúcar medido, espalhe nos bolinhos frios e decore com morangos."],"ingredients":["120 g de farinha de trigo branca","90 g de açúcar","100 g de ovos inteiros batidos (cerca de 2 ovos grandes)","60 g de manteiga sem sal amolecida","60 g de leite integral","100 g de morangos picados bem pequenos","80 g de cream cheese tradicional amolecido (cobertura)","20 g de açúcar (cobertura)","1 g de bicarbonato de sódio"]},"78":{"title":"Batatas recheadas em formato de barquinho","steps":["Lave quatro batatas russet. Um adulto assa até ficarem macias e deixa esfriar o suficiente para manusear.","Aaria pode retirar o centro já frio com uma colher, deixando uma casca firme. Um adulto cuida das batatas ainda quentes ou de utensílios afiados.","Amasse a batata com o brócolis cozido, o milho escorrido, o iogurte e o cheddar medido. Coloque o recheio de volta nas cascas.","Um adulto leva os barquinhos de volta ao forno até o recheio ficar bem quente e o queijo derreter. Deixe esfriar até uma temperatura segura antes de servir."],"ingredients":["600 g de batata russet assada com polpa e casca (4 batatas pequenas/médias)","120 g de brócolis cozido e escorrido","100 g de milho doce em conserva escorrido","80 g de cheddar ralado","60 g de iogurte grego integral natural","1 g de sal fino"]},"79":{"title":"Arroz frito com frango","steps":["Um adulto prepara e resfria o arroz com segurança, cozinha bem o frango e o corta em cubos. Meça o arroz frio, o frango, as ervilhas e a cenoura.","Aaria pode ajudar a medir os ingredientes cozidos em uma tigela. Um adulto quebra e bate os ovos e lava as mãos e os utensílios depois.","Um adulto aquece o azeite em uma frigideira, mexe o ovo até ficar totalmente cozido e acrescenta o arroz, o frango, as ervilhas, a cenoura, o sal e a pimenta. Mexe até tudo ficar bem quente.","Um adulto serve o arroz em quatro tigelas e confere se o frango e o ovo estão totalmente cozidos e quentes. Deixe esfriar com segurança antes de comer."],"ingredients":["600 g de arroz branco de grão longo cozido e refrigerado","200 g de peito de frango sem pele cozido e picado","100 g de ervilhas cozidas e escorridas","100 g de cenoura cozida em cubos","100 g de ovo inteiro batido (cerca de 2 ovos grandes)","9 g de azeite","1 g de sal fino","0,5 g de pimenta-do-reino moída"]},"80":{"title":"Quadradinhos de polenta com queijo","steps":["Meça o fubá, o leite, a água, o queijo e os temperos. Aaria pode misturar o fubá seco e o orégano em uma tigela.","Um adulto aquece a água e o leite até quase ferver e acrescenta o fubá aos poucos, mexendo até engrossar e cozinhar por completo. Mantenha Aaria longe da panela quente e dos respingos.","Quando a mistura esfriar e estiver segura para tocar, Aaria pode misturar o ovo batido e o queijo com um adulto. Espalhe em uma forma untada e forrada e leve à geladeira até firmar.","Um adulto corta a polenta firme em dezesseis quadradinhos e assa até dourar levemente e ficar bem quente. Deixe esfriar antes de servir."],"ingredients":["160 g de fubá amarelo enriquecido","500 g de água","250 g de leite integral","100 g de muçarela ralada","50 g de ovo inteiro batido (cerca de 1 ovo grande)","9 g de azeite","1 g de sal fino","0,5 g de orégano seco"]},"81":{"title":"Sopa cremosa arco-íris de milho","ingredients":["180 g de milho-doce escorrido","300 g de batata cozida, descascada e em cubos","100 g de cenoura cozida em cubos","400 g de leite integral","60 g de cebola picada","8 g de azeite","1 g de sal de mesa"],"steps":["Lave as mãos. Separe a batata cozida, a cenoura cozida, o milho escorrido, o leite, a cebola, o azeite e o sal. Um adulto deve escorrer e pesar os ingredientes quentes.","Com um adulto, coloque o azeite e a cebola em uma panela e cozinhe em fogo baixo até amaciar. O adulto manuseia o fogão e a panela quente.","Junte a batata, a cenoura, o milho, o leite e o sal. O adulto aquece em fervura branda e mexe até ficar bem quente; não deixe transbordar.","O adulto desliga o fogão e divide a sopa em quatro tigelas. Espere esfriar até uma temperatura segura antes de servir."],"description":"Uma sopa suave e cremosa de milho-doce, batata e cenoura, preparada para compartilhar.","safety":"Contém leite. Um adulto manuseia o fogão, a panela e a sopa quentes. Use vegetais totalmente cozidos e sirva somente depois de esfriar até uma temperatura segura. Confira avisos de contaminação cruzada nos rótulos.","allergyAlert":"Alerta de alergia: contém leite. Confira os rótulos dos ingredientes embalados para verificar contaminação cruzada.","equipment":["Panela","Fogão","Colher de pau","Balança de cozinha","Quatro tigelas"],"category":"Cozinhando com amigos","method":"Hob"},"82":{"title":"Rolinhos arco-íris de papel de arroz","ingredients":["8 folhas de papel de arroz (64 g de peso seco total)","80 g de cenoura crua em tiras finas","80 g de pepino em tiras finas","80 g de pimentão vermelho cru em tiras finas","20 g de folhas de alface crespa"],"steps":["Lave as mãos e os vegetais. Um adulto corta a cenoura, o pepino e o pimentão em tiras finas; deixe as folhas de alface por perto.","Um adulto amolece uma folha de papel de arroz conforme as instruções da embalagem e a coloca sobre uma tábua limpa e úmida.","Aaria e os amigos colocam um pouco de alface e algumas tiras coloridas perto da borda inferior, deixando espaço nas laterais.","Dobre as laterais para dentro e enrole sem apertar demais. Repita para fazer oito rolinhos; sirva logo. Se precisar cortar, peça a um adulto."],"description":"Cenoura, pepino, pimentão e alface crocantes, enrolados em papel de arroz macio.","safety":"Os vegetais não incluem os principais alergênicos listados; a composição e a contaminação cruzada do papel de arroz variam por marca, então um adulto deve conferir a embalagem. Mantenha refrigerado se não for servir imediatamente.","allergyAlert":"Alerta de alergia: os ingredientes do papel de arroz variam; um adulto deve conferir trigo/glúten, soja e contaminação cruzada.","equipment":["Tábua limpa","Faca infantil segura (uso por adulto)","Prato raso","Tábua limpa e úmida"],"category":"Cozinhando com amigos","method":"No-cook"},"83":{"title":"Barquinhos de sushi de pepino","ingredients":["320 g de pepino com casca, lavado","180 g de arroz branco glutinoso cozido e frio","60 g de cream cheese tradicional","40 g de cenoura crua ralada fininha","3 g de sementes de gergelim","1 g de sal de mesa"],"steps":["Lave as mãos e os vegetais. Um adulto cozinha o arroz com antecedência, resfria rapidamente e o mantém refrigerado até a montagem.","Um adulto corta os pepinos ao meio no sentido do comprimento e retira um pouco do centro com uma colher, formando uma canaleta. Pique bem o miolo comestível e reserve para o recheio.","Aaria mistura o arroz frio com o cream cheese, o sal e o miolo de pepino picado em uma tigela. Coloque a mistura nas canaletas.","Finalize com cenoura ralada e sementes de gergelim. Um adulto corta cada metade recheada em dois barquinhos; sirva frio e logo após montar."],"description":"Metades frescas de pepino recheadas com arroz cremoso e cobertas com cenoura colorida.","safety":"Contém leite e gergelim. O arroz deve ser resfriado rapidamente e mantido refrigerado; descarte se ficar em temperatura ambiente por mais de 2 horas (1 hora acima de 32 °C). Um adulto manuseia a faca. Não há peixe cru.","allergyAlert":"Alerta de alergia: contém leite e gergelim.","equipment":["Tábua de corte","Faca para adulto","Colher","Tigela","Geladeira"],"category":"Cozinhando com amigos","method":"No-cook with pre-cooked rice"},"84":{"title":"Picolés de banana com chocolate","ingredients":["354 g de banana madura sem casca (cerca de 3 bananas médias)","90 g de gotas de chocolate meio amargo","18 g de coco seco sem açúcar"],"steps":["Lave as mãos. Descasque as bananas e corte cada uma em duas partes iguais. Um adulto pode ajudar com a faca.","Espete um palito próprio para alimentos na ponta cortada de cada pedaço de banana. Coloque os seis pedaços em uma bandeja forrada.","Um adulto derrete o chocolate delicadamente e espera amornar. Aaria espalha o chocolate com uma colher ou pincel, enquanto um amigo acrescenta o coco.","Leve a bandeja ao congelador até firmar e sirva. Um adulto manuseia o chocolate morno; acompanhe o uso dos palitos e retire-os para crianças menores."],"description":"Metades de banana cobertas com chocolate e um toque de coco seco.","safety":"Banana e coco fazem parte da receita. Marcas de chocolate podem conter leite ou soja; confira o rótulo. Um adulto derrete o chocolate. Mantenha congelado até servir e supervisione os palitos para reduzir risco de engasgo ou ferimento.","allergyAlert":"Alerta de alergia: contém coco; o chocolate pode conter leite ou soja. Confira o rótulo e a informação sobre contaminação cruzada.","equipment":["Tábua de corte","Faca infantil segura","Palitos próprios para alimentos","Assadeira forrada","Micro-ondas ou banho-maria","Congelador"],"category":"Cozinhando com amigos","method":"No-cook and freezer set"},"85":{"title":"Mini pitas recheadas com falafel assado","ingredients":["240 g de grão-de-bico cozido, escorrido e seco com papel-toalha","50 g de cebola crua bem picada","25 g de farinha de trigo integral","8 g de azeite","1 g de cominho em pó","8 g de folhas frescas de coentro picadas","1 g de sal de mesa","120 g de mini pães pita integrais (a nutrição varia por marca)","25 g de alface crespa","68 g de tomate cru em cubos","60 g de iogurte natural integral para acompanhar"],"steps":["Lave as mãos. Coloque o grão-de-bico escorrido, a cebola, a farinha, o azeite, o cominho, o coentro e o sal em uma tigela. Amasse até a mistura ficar unida, ainda com pedacinhos.","Com as mãos limpas, modele oito mini hambúrgueres de falafel. Coloque em uma assadeira forrada e lave as mãos novamente.","Um adulto aquece o forno a 200 °C e assa os falafels até ficarem bem quentes por dentro e levemente dourados, virando uma vez com utensílio próprio. O adulto manuseia a assadeira quente.","Quando estiverem frios o bastante para manusear, coloque dois falafels em cada mini pita com alface e tomate. Um adulto abre as pitas e confere o recheio antes de servir."],"description":"Falafel de grão-de-bico dourado no forno, servido em mini pitas integrais com alface e tomate.","safety":"Contém trigo/glúten e leite (molho de iogurte). Confira os rótulos da pita e do grão-de-bico embalado para verificar gergelim, soja ou contaminação cruzada. Um adulto manuseia o forno e a assadeira quente. Asse até ficar bem quente por dentro e lave as mãos após manusear os ingredientes.","allergyAlert":"Alerta de alergia: contém trigo/glúten e leite. Confira os ingredientes embalados para verificar gergelim, soja e contaminação cruzada.","equipment":["Tigela","Garfo ou amassador de batata","Assadeira forrada","Forno","Luvas térmicas","Faca infantil segura","Prato para servir"],"category":"Cozinhando com amigos","method":"Oven · adult-supervised"},"86":{"title":"Pretzels Coloridos com Molhos","steps":["Lave o pepino, o pimentão e a cenoura e seque-os.","Misture o cream cheese e o iogurte em uma tigela pequena até ficar cremoso. Divida o molho em duas tigelinhas.","Arrume os pretzels e os palitos coloridos de legumes ao redor dos molhos em uma travessa.","Escolha um pretzel ou palito de legume, mergulhe no molho e aproveite o lanche crocante e colorido."],"ingredients":["80 g de mini pretzels salgados","80 g de cream cheese","80 g de iogurte natural integral","60 g de pepino em palitos","60 g de pimentão vermelho em tiras","60 g de cenoura em palitos"],"safety":"Confira nos rótulos dos pretzels e do cream cheese os alergênicos e avisos de contato cruzado. Mini pretzels podem ser duros e salgados; sirva com a criança sentada e supervisione durante o consumo."},"87":{"title":"Pipoca Arco-Íris com Frutas","steps":["Peça a um adulto para preparar pipoca simples na pipoqueira de ar e deixe esfriar completamente.","Lave as frutas e as uvas. Um adulto deve descascar o kiwi e cortar as uvas ao meio no sentido do comprimento; use uma faca infantil para picar as frutas macias.","Coloque a pipoca fria e as frutas preparadas em uma tigela grande. Acrescente as gotas de chocolate.","Misture delicadamente e divida em quatro tigelinhas. Coma logo para a fruta não amolecer a pipoca."],"ingredients":["32 g de pipoca simples, já estourada sem óleo","60 g de morangos sem folhas, picados","40 g de mirtilos","40 g de kiwi verde, descascado e picado","40 g de uvas sem sementes, cortadas ao meio no sentido do comprimento por um adulto","16 g de mini gotas de chocolate meio amargo"],"safety":"Um adulto prepara e manuseia o aparelho quente para estourar a pipoca. Retire os grãos que não estouraram antes de servir. Um adulto deve cortar as uvas no sentido do comprimento em pedaços pequenos para reduzir o risco de engasgo para crianças menores. Confira no rótulo do chocolate a presença de leite, soja e avisos de contato cruzado. Sirva a fruta imediatamente e refrigere as sobras sem demora."},"88":{"title":"Copinhos de Mousse de Abacate com Chocolate","steps":["Lave os morangos. Peça a um adulto para retirar o caroço e a casca do abacate; coloque a polpa no copo do liquidificador.","Acrescente o iogurte, o cacau e o açúcar. Um adulto fecha e liga o liquidificador até a mousse ficar cremosa.","Divida a mousse igualmente entre quatro copinhos e leve à geladeira até a hora de servir.","Decore cada copinho com fatias finas de morango e sirva gelado."],"ingredients":["150 g de polpa de abacate maduro, sem caroço e casca","120 g de iogurte grego natural integral","12 g de cacau em pó sem açúcar","20 g de açúcar refinado","40 g de morangos lavados e fatiados finamente"],"safety":"Um adulto retira o caroço do abacate e opera o liquidificador; mantenha mãos e utensílios longe das lâminas em movimento. Confira nos rótulos do cacau e do iogurte os avisos de contato cruzado. Mantenha refrigerado até servir."},"89":{"title":"Salada Arco-Íris de Grão-de-Bico em Potes","steps":["Coloque o grão-de-bico e o milho escorridos em uma tigela limpa.","Acrescente o pepino, o pimentão vermelho e o tomate em cubos; misture com cuidado.","Junte o azeite e o orégano seco e mexa até envolver levemente os vegetais.","Divida a salada em quatro potes limpos e reutilizáveis próprios para alimentos e sirva gelada."],"ingredients":["200 g de grão-de-bico cozido, escorrido e enxaguado","80 g de milho, escorrido","80 g de pepino em cubos","80 g de pimentão vermelho em cubos","80 g de tomate em cubos","10 g de azeite de oliva","1 g de orégano seco"],"safety":"Use grão-de-bico cozido e frio; um adulto abre e escorre a lata antes de cozinhar juntos. Confira os rótulos e avisos de contato cruzado. Mantenha a salada refrigerada se não for servida imediatamente. O grão-de-bico pode causar reações em pessoas com alergia a leguminosas.","allergyAlert":"Alerta de alergia: contém grão-de-bico (uma leguminosa). Confira todos os rótulos e avisos de contato cruzado; não é adequado para quem tem alergia a grão-de-bico ou leguminosas, salvo orientação do responsável.","description":"Uma salada colorida e sem cozimento, servida em quatro potes práticos com grão-de-bico, milho e vegetais crocantes.","method":"Montagem sem cozimento","yieldText":"4 potes · cerca de 133 g cada","fact":"O grão-de-bico é uma leguminosa que fornece proteína vegetal e fibras."},"90":{"title":"Mini Tortinhas de Frutas","steps":["Lave as frutas. Peça a um adulto para aquecer o forno e cortar círculos de massa; pressione-os delicadamente em uma forma de mini muffins.","Um adulto assa as bases até crescerem e ficarem douradas; depois coloca a forma em local seguro para esfriar completamente.","Coloque o iogurte grego nas bases de massa já frias.","Decore cada tortinha com morango, kiwi e mirtilos. Sirva logo."],"ingredients":["180 g de massa folhada pronta para assar, descongelada conforme o rótulo","120 g de iogurte grego natural integral","50 g de morangos lavados e fatiados finamente","40 g de kiwi descascado e fatiado finamente","40 g de mirtilos lavados"],"safety":"Um adulto manuseia o forno, a forma quente e qualquer cortador afiado. Deixe as bases esfriarem completamente antes de rechear. Confira nos rótulos da massa e do iogurte a presença de leite, soja, trigo, glúten e avisos de contato cruzado. Mantenha as tortinhas recheadas refrigeradas se não forem servidas imediatamente."},"91":{"title":"Copinhos de salada de cuscuz com limão e ervas","ingredients":["150 g de cuscuz cozido e frio","1 pepino médio (cerca de 300 g inteiro; use tudo nos copinhos e palitos)","60 g de tomate-cereja bem picado","10 g de suco de limão fresco","5 g de azeite","1 g de orégano seco"],"steps":["Lave o pepino, os tomates e o limão em água corrente. Um adulto prepara o cuscuz e o resfria prontamente na geladeira.","Com um adulto por perto, use um cortador infantil seguro para fazer oito copinhos grossos de pepino; retire um pouco do centro. Guarde o restante para cortar em palitos.","Misture o cuscuz frio, os tomates picados, o suco de limão, o azeite e o orégano em uma tigela.","Coloque a salada nos copinhos de pepino. Sirva logo e mantenha as sobras refrigeradas."],"safety":"Contém trigo/glúten. Um adulto prepara e resfria o cuscuz e supervisiona o cortador infantil. Mantenha o cuscuz cozido refrigerado até servir; não o deixe em temperatura ambiente.","description":"Couscous is made from tiny granules of durum wheat semolina.","difficulty":"Fácil","category":"Cozinhando com amigos","method":"No-cook assembly","allergyAlert":"Contém trigo/glúten. Um adulto prepara e resfria o cuscuz e supervisiona o cortador infantil. Mantenha o cuscuz cozido refrigerado até servir; não o deixe em temperatura ambiente."},"92":{"title":"Bolinha de aveia e chocolate sem forno","ingredients":["90 g de aveia em flocos","60 g de pasta de amendoim cremosa com sal","40 g de creme de chocolate com avelã"],"steps":["Lave e seque as mãos. Coloque a aveia, a pasta de amendoim e o creme de chocolate com avelã em uma tigela.","Misture devagar até toda a aveia ficar coberta e a massa grudar quando apertada.","Com as mãos limpas, faça 12 bolinhas pequenas e iguais. Se a massa estiver grudenta, leve a tigela à geladeira por alguns instantes antes de modelar.","Coloque as bolinhas em um pote tampado e leve à geladeira até firmarem. Mantenha refrigerado; sirva três bolinhas por porção."],"safety":"Contém amendoim, avelã e aveia. Confira no rótulo outros alergênicos (como leite ou soja) e avisos de contaminação cruzada. Lave as mãos e as superfícies; mantenha refrigerado. Use pasta industrializada, sem castanhas inteiras.","description":"Oats are whole cereal grains, and rolling them makes them quick to mix into snacks.","difficulty":"Fácil","category":"Cozinhando com amigos","method":"No-cook assembly","allergyAlert":"Contém amendoim, avelã e aveia. Confira no rótulo outros alergênicos (como leite ou soja) e avisos de contaminação cruzada. Lave as mãos e as superfícies; mantenha refrigerado. Use pasta industrializada, sem castanhas inteiras."},"93":{"title":"Cogumelos recheados com espinafre e queijo","ingredients":["8 cogumelos brancos pequenos (160 g de parte comestível), sem os talos","40 g de espinafre cru, bem picado","35 g de muçarela ralada","20 g de farinha de rosca seca e simples","5 g de azeite"],"steps":["Peça a um adulto para aquecer o forno a 190°C, limpar os cogumelos e retirar os talos. Coloque os chapéus em uma assadeira forrada.","Misture o espinafre picado, a muçarela e a farinha de rosca em uma tigela.","Coloque o recheio em cada cogumelo e pincele as bordas levemente com azeite.","Um adulto assa até os cogumelos ficarem macios e o recheio bem quente por dentro, cerca de 15–18 minutos. Espere esfriar antes de comer."],"safety":"Contém leite e trigo/glúten. Um adulto cuida do forno e da assadeira quente. Limpe os cogumelos com segurança, use tábua separada para os vegetais e asse até o recheio ficar bem quente.","description":"Mushrooms are fungi, not plants.","difficulty":"Fácil","category":"Cozinhando com amigos","method":"Oven-baked","allergyAlert":"Contém leite e trigo/glúten. Um adulto cuida do forno e da assadeira quente. Limpe os cogumelos com segurança, use tábua separada para os vegetais e asse até o recheio ficar bem quente."},"94":{"title":"Copinhos de pudim de chia com manga e coco","ingredients":["30 g de sementes de chia secas","250 g de leite integral","120 g de polpa de manga madura em cubinhos","15 g de coco seco ralado sem açúcar"],"steps":["Lave e seque as mãos. Misture as sementes de chia ao leite em uma tigela.","Espere 10 minutos e misture de novo para evitar grumos. Tampe e deixe na geladeira até engrossar, de preferência durante a noite.","Lave a casca da manga e peça a um adulto para descascar e cortar a fruta. Mantenha refrigerada até servir.","Confira se a chia absorveu o leite e está totalmente hidratada; nunca sirva as sementes secas. Coloque o pudim em quatro copinhos, cubra com manga e coco ralado e sirva gelado."],"safety":"Contém leite e coco. Confira no rótulo os avisos de alergia e contaminação cruzada e confirme se cada criança pode consumir chia com segurança. Nunca sirva chia seca; confirme que hidratou totalmente no leite. Um adulto descasca e corta a manga. Mantenha refrigerado.","description":"Chia seeds absorb liquid and form a soft gel as they rest.","difficulty":"Fácil","category":"Cozinhando com amigos","method":"No-cook assembly","allergyAlert":"Contém leite e coco. Confira no rótulo os avisos de alergia e contaminação cruzada e confirme se cada criança pode consumir chia com segurança. Nunca sirva chia seca; confirme que hidratou totalmente no leite. Um adulto descasca e corta a manga. Mantenha refrigerado."},"95":{"title":"Nachos arco-íris para compartilhar","ingredients":["2 tortilhas pequenas integrais (82 g no total)","5 g de azeite","80 g de milho-doce em conserva, escorrido","60 g de tomate maduro em cubinhos","40 g de pimentão vermelho em cubinhos","50 g de queijo cheddar ralado"],"steps":["Peça a um adulto para aquecer o forno a 180°C. Pincele os dois lados das tortilhas com uma camada bem fina de azeite.","Um adulto corta cada tortilha em triângulos pequenos. Arrume em uma camada só numa assadeira forrada.","Espalhe o milho escorrido, o tomate, o pimentão e o cheddar por cima dos triângulos.","Um adulto assa até as bordas ficarem crocantes e o queijo derreter, cerca de 8–10 minutos. Espere esfriar um pouco antes de compartilhar."],"safety":"Contém trigo/glúten e leite. Um adulto corta, usa o forno e retira a assadeira quente. Escorra o milho e use tábuas limpas para os vegetais crus.","description":"Nachos are often served as a shareable snack, so everyone can choose a colourful bite.","difficulty":"Fácil","category":"Cozinhando com amigos","method":"Oven-baked","allergyAlert":"Contém trigo/glúten e leite. Um adulto corta, usa o forno e retira a assadeira quente. Escorra o milho e use tábuas limpas para os vegetais crus."}});
