Object.assign(STEP_GUIDES,{"66":[{"title":"Put the flour in a bowl","emoji":"🥣","tip":"Put the flour in a bowl. Crack in the eggs and add the measured water. Mix, then knead into a smooth dough. Wash hands after handling raw egg."},{"title":"Dust the board lightly with flour,","emoji":"🌈","tip":"Dust the board lightly with flour, then roll the dough into thin sheets with a wooden rolling pin. Cut broad pasta sheets with a blunt pastry cutter."},{"title":"Spread a little tomato sauce in th","emoji":"✨","tip":"Spread a little tomato sauce in the baking dish. Add pasta, courgette, carrot and mozzarella in layers; repeat, finishing with sauce and cheese."},{"title":"An adult places the dish in a preh","emoji":"🍽️","tip":"An adult places the dish in a preheated oven at 180°C and bakes until the pasta is tender and the centre is piping hot, about 25–30 minutes. An adult removes it; cool before serving."}],"67":[{"title":"Preparar massa e recheio","emoji":"🥣","tip":"Mix the wholemeal flour and salt in a bowl. Add the measured water gradually and knead into a soft dough. Cover and rest. While it rests, crumble the paneer and mix in the chopped coriander and cumin."},{"title":"Rechear e fechar","emoji":"🌈","tip":"Divide the dough into four equal balls and flatten each one. Add one quarter of the paneer filling to each, then seal the dough around it."},{"title":"Abrir com rolo de madeira","emoji":"✨","tip":"Dust the board lightly with flour. Roll each filled ball gently into a round paratha with a wooden rolling pin."},{"title":"Adulto cozinha na frigideira","emoji":"🍽️","tip":"An adult cooks each paratha in a lightly oiled hot pan until both sides are cooked through and spotted golden. The adult manages the hob; let the parathas cool before serving."}],"68":[{"title":"Wash hands","emoji":"🥣","tip":"Wash hands. Set out the rolls, washed lettuce and measured cheese. An adult cuts the tomato and onion with a knife."},{"title":"An adult shapes the raw ground chi","emoji":"🌈","tip":"An adult shapes the raw ground chicken and onion into four small patties and cooks them in a lightly oiled pan. A food thermometer must show 74°C at the centre. Keep raw chicken utensils separate."},{"title":"After the patties are fully cooked","emoji":"✨","tip":"After the patties are fully cooked, Aaria builds each burger with a patty, mozzarella, lettuce and tomato inside a roll."},{"title":"Place the mini burgers on a clean ","emoji":"🍽️","tip":"Place the mini burgers on a clean plate and serve once safely cooled. Wash hands, board and utensils that touched raw chicken."}],"69":[{"title":"Rinse the rice in a fine sieve unt","emoji":"🥣","tip":"Rinse the rice in a fine sieve until the water runs mostly clear. Drain it while the measured vegetables and spices are prepared."},{"title":"Measure the cooked peas, carrot an","emoji":"🌈","tip":"Measure the cooked peas, carrot and cauliflower. An adult finely chops the onion; Aaria measures the tomato, spices and salt into bowls."},{"title":"An adult heats the oil in a deep p","emoji":"✨","tip":"An adult heats the oil in a deep pot, softens the onion, adds tomato and spices, then stirs in rice, vegetables and measured water. Cover and cook gently until the rice is tender and water is absorbed."},{"title":"An adult turns off the hob and con","emoji":"🍽️","tip":"An adult turns off the hob and confirms the pot is safe. Aaria gently fluffs the rice with a fork and serves it into bowls; cool before eating."}],"70":[{"title":"Abrir a massa folhada","emoji":"🥣","tip":"Aaria rolls the pastry on a clean board and sets out four small pie tins. An adult prepares the thick butter, flour and milk sauce, mixes it with the cooked chicken and vegetables, then cools the filling before use."},{"title":"Rechear e fechar as tortinhas","emoji":"🌈","tip":"Spoon the cooled filling into the pastry cases, cover each with a pastry lid and seal the edges gently using a blunt pastry tool."},{"title":"Adulto assa com segurança","emoji":"✨","tip":"An adult places the pies in a preheated 200°C oven and bakes until the pastry is puffed and golden and the filling is piping hot. The adult handles the oven and hot tins."},{"title":"Esfriar e servir","emoji":"🍽️","tip":"An adult checks that the filling is steaming hot throughout, then removes the pies and lets them cool. Aaria helps serve the cooled pies on a clean plate."}],"71":[{"title":"Stir the pudding base","emoji":"🥣","tip":"Aaria measures the cooked rice, milk, condensed milk, coconut and salt into a saucepan. With the hob switched off, she stirs them together; an adult stays beside her."},{"title":"Warm it gently","emoji":"🌈","tip":"An adult turns the hob to low and stays at the pan. Aaria watches from the safe side of the counter and tells the adult when to stir; the adult warms the mixture gently, stirring often, until creamy. Do not let it boil."},{"title":"Check the creamy texture","emoji":"✨","tip":"The adult switches off the hob and moves the pan to a heat-safe area. Everyone waits until the pudding is warm, not hot. Check it is creamy and the rice is tender; the adult handles the hot pan."},{"title":"Spoon into cups and finish","emoji":"🍽️","tip":"Aaria spoons the cooled pudding into four small cups with an adult nearby. Refrigerate promptly if not eating straight away."}],"72":[{"title":"Prepare the mild sauce","emoji":"🥣","tip":"Aaria checks the ingredients and measures the cumin, turmeric and salt. An adult cuts the paneer and onion with a sharp knife; Aaria can place the paneer in a bowl and measure the milk."},{"title":"Cook the tomato mixture","emoji":"🌈","tip":"An adult heats the oil and butter in a deep pan on medium-low heat, then cooks the onion until soft. Add the chopped tomatoes and spices; the adult stirs until the tomatoes soften into a sauce."},{"title":"Add paneer and milk","emoji":"✨","tip":"The adult adds the paneer cubes and milk and gently simmers until the paneer is hot throughout and the sauce is smooth. Aaria stays at the safe side of the counter and directs the adult; the adult handles the hot pan and spoon."},{"title":"Serve the gentle curry","emoji":"🍽️","tip":"The adult turns off the hob and moves the pan to a heat-safe place. Serve small portions with rice or roti prepared separately; let the curry cool to a safe eating temperature."}],"73":[{"title":"Prepare the pastry case","emoji":"🥣","tip":"Aaria unrolls the pastry with an adult nearby and presses it gently into a 20 cm tart tin. An adult trims the pastry and pricks the base with a fork. Keep the tin on a stable work surface."},{"title":"Mix the colourful filling","emoji":"🌈","tip":"Aaria whisks the eggs and milk in a bowl and stirs in the drained sweetcorn and grated cheddar. An adult finely chops the onion and spinach; add them to the bowl and mix."},{"title":"Fill the quiche","emoji":"✨","tip":"Pour the filling into the pastry case. Aaria can help sprinkle the spinach evenly. An adult places the tin on a baking tray and transfers it to the preheated oven."},{"title":"Bake with an adult","emoji":"🍽️","tip":"An adult bakes at 200°C until the pastry is golden and the egg filling is fully set in the centre, about 25–30 minutes. The adult removes the hot tin and lets the quiche cool before slicing."}],"74":[{"title":"Make the soft dough","emoji":"🥣","tip":"Aaria mixes the flour and measured olive oil in a bowl, then adds the water a little at a time and kneads into a soft dough. Cover the bowl while the filling is prepared."},{"title":"Mix the vegetable filling","emoji":"🌈","tip":"Mash the already-cooked potato with the peas, carrot, cumin, coriander and salt. Aaria can stir and mash with a fork; an adult checks the vegetables are cool enough to handle."},{"title":"Fold and seal triangles","emoji":"✨","tip":"An adult divides the dough into eight pieces and rolls each into a small oval. Aaria places a spoonful of filling in the centre; fold into a triangle and press the edges firmly closed. Do not overfill."},{"title":"Bake until golden","emoji":"🍽️","tip":"Aaria brushes the samosas lightly with the measured oil. An adult arranges them on a lined tray and bakes at 200°C until golden and crisp, about 20–25 minutes. The adult handles the hot oven and tray."}],"75":[{"title":"Mix and rest the pasta dough","emoji":"🥣","tip":"Aaria mixes the flour and salt in a bowl, then adds the eggs, water and olive oil. Stir and knead until a firm dough forms. An adult helps if the dough feels stiff; cover and rest while making the filling."},{"title":"Prepare the cooked filling","emoji":"🌈","tip":"Use only chicken that has already been fully cooked, cooled and kept refrigerated. Aaria mixes the shredded chicken with spinach and mozzarella. An adult checks for bones and chops the spinach finely."},{"title":"Shape and seal ravioli","emoji":"✨","tip":"An adult rolls the dough thinly on a floured surface. Aaria places small mounds of filling about 4 cm apart, covers with another sheet, presses around each mound to remove air and seals the edges. An adult cuts the ravioli with a blunt pasta cutter."},{"title":"Cook gently and serve","emoji":"🍽️","tip":"An adult lowers ravioli into a large pan of gently boiling water and cooks until the pasta is tender and the filling is steaming hot. Lift out with a slotted spoon; the adult handles boiling water. Serve after checking the centre is hot and allowing it to cool."}],"76":[{"title":"Wash and prepare","emoji":"🥣","tip":"Wash the carrot and pepper. An adult cooks the noodles, broccoli and peas, then cools them safely."},{"title":"Arrange the cooled ingredients","emoji":"🌈","tip":"With clean hands, arrange the cooled noodles and vegetables in a large bowl. Aaria can use child-safe tongs to add the colourful vegetables."},{"title":"Toss with oil and salt","emoji":"✨","tip":"Drizzle over the measured olive oil and sprinkle the measured salt. Toss gently until the colours are mixed through."},{"title":"Serve the rainbow bowls","emoji":"🍽️","tip":"Share the noodle toss between four bowls and check that every piece is cool before eating."}],"77":[{"title":"Wash the strawberries","emoji":"🥣","tip":"Wash and finely chop the strawberries. Set aside a few small pieces for the topping."},{"title":"Mix the cupcake batter","emoji":"🌈","tip":"With an adult, beat the softened butter and sugar until creamy. Mix in the eggs, then fold in the flour, baking soda and milk. Fold in the chopped strawberries."},{"title":"Fill the paper cases","emoji":"✨","tip":"Spoon the batter evenly into eight paper cases in a muffin tin. An adult checks that the oven is preheated to 180°C and bakes until the centres are set."},{"title":"Bake, cool and decorate","emoji":"🍽️","tip":"An adult removes the hot tin and cools the cupcakes fully. Mix cream cheese with the measured icing sugar, spread on the cool cakes, and add strawberry pieces."}],"78":[{"title":"Wash and bake the potatoes","emoji":"🥣","tip":"Wash four russet potatoes. An adult bakes them until soft, then lets them cool enough to handle."},{"title":"Scoop the cooled centres","emoji":"🌈","tip":"Aaria can scoop the cooled centres into a bowl, leaving a sturdy potato shell. An adult handles any hot potatoes or sharp tools."},{"title":"Mix the colourful filling","emoji":"✨","tip":"Mash the potato with the cooked broccoli, drained corn, yoghurt and measured cheddar. Spoon the filling back into the shells."},{"title":"Fill, reheat and cool","emoji":"🍽️","tip":"An adult returns the boats to the oven until the filling is piping hot and the cheese is melted. Cool to a safe eating temperature before serving."}],"79":[{"title":"Prepare cooked ingredients","emoji":"🥣","tip":"An adult prepares and chills the rice safely, cooks the chicken thoroughly, and dices it. Measure the cooled rice, chicken, peas and carrot."},{"title":"Measure and beat the egg","emoji":"🌈","tip":"Aaria can help measure the cooked ingredients into a bowl. An adult cracks and beats the eggs, washing hands and equipment afterwards."},{"title":"Adult stir-fries until hot","emoji":"✨","tip":"An adult heats the oil in a pan, scrambles the egg until fully set, then adds the cooked rice, chicken, peas, carrot, salt and pepper. Stir until steaming hot throughout."},{"title":"Serve the four bowls","emoji":"🍽️","tip":"An adult serves the fried rice into four bowls and checks that the chicken and egg are hot and fully cooked. Let it cool safely before eating."}],"80":[{"title":"Measure cornmeal and cheese","emoji":"🥣","tip":"Measure the cornmeal, milk, water, cheese and seasonings. Aaria can stir the dry cornmeal and oregano together in a bowl."},{"title":"Adult cooks the polenta","emoji":"🌈","tip":"An adult brings the water and milk to a gentle simmer, then slowly whisks in cornmeal until thick and fully cooked. Keep Aaria away from the hot pot and splashes."},{"title":"Cool, mix and press","emoji":"✨","tip":"After the mixture cools until safe to handle, Aaria can fold in beaten egg and cheese with an adult. Spread it in an oiled lined tray and chill until firm."},{"title":"Adult bakes golden squares","emoji":"🍽️","tip":"An adult cuts the firm polenta into sixteen squares and bakes them until lightly golden and hot. Let the squares cool before serving."}],"81":[{"title":"Prepare ingredients","emoji":"🥣","tip":"Wash your hands. Put the cooked potato, cooked carrot, drained sweetcorn, milk, onion, oil and salt on the worktop. An adult should drain and weigh hot ingredients."},{"title":"Make the filling","emoji":"🌈","tip":"With an adult, add the oil and onion to a saucepan. Cook gently until soft; the adult handles the hob and hot pan."},{"title":"Assemble together","emoji":"✨","tip":"Add the potato, carrot, sweetcorn, milk and salt. The adult brings it to a gentle simmer and stirs until piping hot; do not let it boil over."},{"title":"Finish and serve","emoji":"🍽️","tip":"The adult turns off the hob and portions the chowder into four bowls. Let it cool to a safe eating temperature before serving."}],"82":[{"title":"Prepare ingredients","emoji":"🥣","tip":"Wash your hands and rinse the vegetables. An adult cuts the carrot, cucumber and pepper into thin sticks; set the lettuce leaves nearby."},{"title":"Make the filling","emoji":"🌈","tip":"An adult softens one rice-paper wrapper according to its packet directions, then lays it flat on a clean damp board."},{"title":"Assemble together","emoji":"✨","tip":"Aaria and friends place a little lettuce and a few colourful vegetable sticks near the lower edge, leaving space at the sides."},{"title":"Finish and serve","emoji":"🍽️","tip":"Fold the sides inward and roll snugly away from you. Repeat to make eight rolls; serve promptly, cut by an adult if needed."}],"83":[{"title":"Prepare ingredients","emoji":"🥣","tip":"Wash your hands and vegetables. An adult cooks the rice ahead, chills it promptly, then keeps it refrigerated until assembly."},{"title":"Make the filling","emoji":"🌈","tip":"An adult halves the cucumbers lengthways and scoops a shallow channel from each half with a spoon. Finely chop the edible scooped cucumber and save it for the filling."},{"title":"Assemble together","emoji":"✨","tip":"Aaria mixes the cooled rice with cream cheese, salt and the chopped cucumber flesh in a bowl. Spoon the mixture into the cucumber channels."},{"title":"Finish and serve","emoji":"🍽️","tip":"Top with grated carrot and sesame seeds. An adult cuts each filled half into two small boats; serve chilled and promptly."}],"84":[{"title":"Prepare ingredients","emoji":"🥣","tip":"Wash your hands. Peel the bananas and cut each into two equal pieces. An adult can help with the knife."},{"title":"Make the filling","emoji":"🌈","tip":"Push a food-safe lolly stick into the cut end of each banana piece. Place the six pieces on a lined tray."},{"title":"Assemble together","emoji":"✨","tip":"An adult melts the chocolate gently and lets it cool slightly. Aaria spoons or brushes chocolate over each banana while a friend adds coconut."},{"title":"Finish and serve","emoji":"🍽️","tip":"Freeze the tray until firm, then serve. An adult handles warm chocolate; supervise sticks while eating and remove them for younger children."}],"85":[{"title":"Prepare ingredients","emoji":"🥣","tip":"Wash your hands. Add the drained chickpeas, onion, flour, olive oil, cumin, coriander and salt to a bowl. Mash until the mixture holds together but still has small pieces."},{"title":"Make the filling","emoji":"🌈","tip":"With clean hands, shape the mixture into eight small falafel patties. Place them on a lined baking tray and wash hands again."},{"title":"Assemble together","emoji":"✨","tip":"An adult heats the oven to 200°C and bakes the falafel until hot through and lightly browned, turning once with an oven-safe utensil. The adult handles the hot tray."},{"title":"Finish and serve","emoji":"🍽️","tip":"Once cooled enough to handle, place two falafel in each mini pita pocket with lettuce, tomato and yogurt dip. An adult opens the pitas and checks the hot filling before serving."}],"86":[{"title":"Wash the rainbow veg","emoji":"🥣","tip":"Wash the cucumber, pepper and carrot, then dry them."},{"title":"Mix the creamy dip","emoji":"🌈","tip":"Stir the cream cheese and yoghurt together in a small bowl until smooth. Put the dip in two little bowls."},{"title":"Build the platter","emoji":"✨","tip":"Arrange the pretzels and colourful vegetable sticks around the dips on a platter."},{"title":"Dip and enjoy","emoji":"🍽️","tip":"Choose a pretzel or vegetable stick, dip it, and enjoy the crunchy rainbow snack."}],"87":[{"title":"Prepare and cool popcorn","emoji":"🥣","tip":"Ask an adult to prepare plain air-popped popcorn and let it cool completely."},{"title":"Wash and cut the fruit","emoji":"🌈","tip":"Wash the berries, kiwi and grapes. An adult should peel the kiwi and halve the grapes lengthways; use a child-safe knife to dice the soft fruit."},{"title":"Add the rainbow fruit","emoji":"✨","tip":"Put the cooled popcorn and prepared fruit into a large bowl. Sprinkle in the chocolate chips."},{"title":"Mix and serve fresh","emoji":"🍽️","tip":"Toss gently and divide into four small bowls. Eat straight away so the fruit does not soften the popcorn."}],"88":[{"title":"Prepare the avocado","emoji":"🥣","tip":"Wash the strawberries. Ask an adult to remove the avocado stone and skin; scoop the flesh into the blender jug."},{"title":"Blend the mousse","emoji":"🌈","tip":"Add the yoghurt, cocoa powder and sugar. An adult secures and operates the blender until the mousse is smooth."},{"title":"Fill and chill the cups","emoji":"✨","tip":"Spoon the mousse evenly into four small cups and chill until ready to serve."},{"title":"Add strawberry tops","emoji":"🍽️","tip":"Top each cup with thin strawberry slices and enjoy chilled."}],"89":[{"title":"Add the chickpeas and corn","emoji":"🥣","tip":"Put the drained chickpeas and sweetcorn into a clean mixing bowl."},{"title":"Mix in the rainbow vegetables","emoji":"🌈","tip":"Add the diced cucumber, red pepper and tomato, then stir gently."},{"title":"Season the salad","emoji":"✨","tip":"Mix in the olive oil and dried oregano until the vegetables are lightly coated."},{"title":"Fill the jars and serve","emoji":"🍽️","tip":"Spoon the salad evenly into four clean, reusable food-safe jars and serve chilled."}],"90":[{"title":"Shape the pastry cases","emoji":"🥣","tip":"Wash the fruit. Ask an adult to preheat the oven and cut pastry circles; press them gently into a mini muffin tin."},{"title":"Bake and cool safely","emoji":"🌈","tip":"An adult bakes the pastry cases until puffed and golden, then places the tin on a safe surface to cool completely."},{"title":"Fill with yoghurt","emoji":"✨","tip":"Spoon Greek yoghurt into the cooled pastry cases."},{"title":"Top with fresh fruit","emoji":"🍽️","tip":"Decorate each tart with strawberry, kiwi and blueberries. Serve promptly."}],"91":[{"title":"Wash and cool ingredients","emoji":"🥣","tip":"Wash the cucumber, tomatoes and lemon under cool running water. An adult prepares the couscous, then cools it promptly in the fridge."},{"title":"Prepare cucumber cups","emoji":"🌈","tip":"With an adult nearby, use a child-safe crinkle cutter to make eight thick cucumber cups; scoop a shallow hollow from each. Save the extra cucumber for sticks."},{"title":"Mix the lemon-herb couscous","emoji":"✨","tip":"Stir the cooled couscous, chopped tomatoes, lemon juice, olive oil and oregano together in a bowl."},{"title":"Fill and serve","emoji":"🍽️","tip":"Spoon the salad into the cucumber cups. Serve straight away and keep leftovers chilled."}],"92":[{"title":"Measure the ingredients","emoji":"🥣","tip":"Wash and dry hands. Measure the oats, peanut butter and chocolate-hazelnut spread into a mixing bowl."},{"title":"Mix until sticky","emoji":"🌈","tip":"Stir slowly until all the oats are coated and the mixture sticks together when pressed."},{"title":"Roll 12 small balls","emoji":"✨","tip":"With clean hands, roll the mixture into 12 equal small balls. If it feels sticky, chill the bowl briefly before shaping."},{"title":"Chill and share","emoji":"🍽️","tip":"Place the balls in a covered container and refrigerate until firm. Keep chilled; enjoy three balls per serving."}],"93":[{"title":"Prepare mushrooms safely","emoji":"🥣","tip":"Ask an adult to preheat the oven to 190°C, clean the mushrooms and remove the stems. Put the caps on a lined baking tray."},{"title":"Mix spinach filling","emoji":"🌈","tip":"Mix the chopped spinach, grated mozzarella and breadcrumbs in a bowl."},{"title":"Fill the caps","emoji":"✨","tip":"Spoon the filling into each mushroom cap and brush the edges lightly with olive oil."},{"title":"Bake until piping hot","emoji":"🍽️","tip":"An adult bakes the caps until tender and the filling is piping hot throughout, about 15–18 minutes. Let them cool before eating."}],"94":[{"title":"Stir chia into milk","emoji":"🥣","tip":"Wash and dry hands. Stir the chia seeds into the milk in a bowl until evenly mixed."},{"title":"Stir again and chill","emoji":"🌈","tip":"Wait 10 minutes, then stir again so the seeds do not clump. Cover and refrigerate until thick, preferably overnight."},{"title":"Prepare mango safely","emoji":"✨","tip":"Wash the mango skin, then ask an adult to peel and dice the fruit. Keep the fruit chilled until serving."},{"title":"Top and serve chilled","emoji":"🍽️","tip":"Check that the chia is fully swollen and hydrated in the milk; never serve it dry. Spoon the pudding into four cups, top with mango and desiccated coconut, and serve chilled."}],"95":[{"title":"Brush tortillas","emoji":"🥣","tip":"Ask an adult to preheat the oven to 180°C. Brush both sides of the tortillas very lightly with olive oil."},{"title":"Cut and arrange triangles","emoji":"🌈","tip":"An adult cuts each tortilla into small triangles. Arrange them in one layer on a lined baking tray."},{"title":"Add rainbow toppings","emoji":"✨","tip":"Scatter the drained sweetcorn, diced tomato, diced pepper and grated cheddar evenly over the tortilla triangles."},{"title":"Bake and cool","emoji":"🍽️","tip":"An adult bakes until the edges are crisp and the cheese has melted, about 8–10 minutes. Cool briefly before sharing."}]});
