Object.assign(PT_TRANSLATIONS,{Oregano:"Orégano"},{"Put your creation somewhere safe to cool or chill. Set a timer and tidy up your ingredients while you wait.": "Coloque sua criação em um local seguro para esfriar ou resfriar. Programe um temporizador e organize os ingredientes enquanto espera.", "a pinch of salt and pepper": "Uma pitada de sal e pimenta-do-reino", "lettuce or thin tomato slice": "alface ou fatias finas de tomate", "rolled oat": "aveia em flocos", "oat": "aveia", "chilled chicken": "frango resfriado", "a pinch of ground cumin": "Uma pitada de cominho moído", "thick greek yogurt": "iogurte grego espesso", "sugar": "açúcar", "tomato pizza sauce": "molho de tomate para pizza", "No recipes here yet.": "Nenhuma receita por aqui ainda."},PT_WORDS,PT_YIELDS,{"tomato pizza sauce": "molho de tomate para pizza", "bread slice": "fatia de pão", "sandwich bread": "pão de forma", "slider buns": "pãezinhos para mini-hambúrguer", "grated mozzarella": "muçarela ralada", "tomato slices": "fatias de tomate", "sweet potato": "batata-doce", "pinch of salt": "pitada de sal", "salt and pepper": "sal e pimenta-do-reino", "cooked mashed potato": "batata cozida e amassada", "plain Greek yogurt": "iogurte grego natural", "cream cheese": "cream cheese", "fully cooked chicken nuggets": "nuggets de frango completamente preparados", "pasta de amendoim or sunflower seed butter": "pasta de amendoim ou de sementes de girassol", "1 of": "1 de", "equal servings": "porções iguais", "No recipes here yet.": "Nenhuma receita por aqui ainda.", "Favourite recipes": "Receitas favoritas", "Favorite recipes": "Receitas favoritas"});
function stepDisplayText(t){const v=t.replace(/Ask an adult to /ig,'').replace(/Have an adult /ig,'').replace(/With an adult, /ig,'').replace(/\bAn adult /ig,'').replace(/\bAdult /ig,'').replace(/adult-cut /ig,'cut ');return (v.charAt(0).toUpperCase()+v.slice(1)).replace(/^(Cuts|Cores|Cooks|Peels|Blends|Adds|Operates)\b/,m=>m.slice(0,-1)).replace(/^Air-fries\b/,'Air-fry').replace(/; peels and cuts /,'; peel and cut ').replace(/; blends /,'; blend ')}
const STEP_DISPLAY_OVERRIDES={"1": ["Flatten the bread slices and press each into an air-fryer-safe silicone muffin cup.", "Whisk eggs, milk, cheese and a pinch of salt in a bowl.", "Pour the mixture into the bread cups, leaving space at the top.", "Air-fry at 160°C for 8–12 minutes, until the egg is completely set. Cool before eating."], "2": ["Cook nuggets completely according to their package instructions.", "Split the buns. Spread a little ketchup if you like.", "Put 1–2 cooked nuggets into each bun and add cheese.", "Air-fry the assembled buns at 160°C for 4–7 minutes, until the cheese melts and everything is hot. Add lettuce after heating."], "3": ["Flatten each bread slice with a rolling pin or your hands.", "Spread a thin layer of chocolate spread over each slice.", "Peel the banana, break it into small pieces, and place them near one edge.", "Roll tightly; brush lightly with butter if using.", "Air-fry at 170°C for 5–7 minutes, until lightly golden. Let the roll-ups cool well; the chocolate filling can be hot."], "4": ["Mix cooled mashed potato with grated cheese and optional corn.", "With clean hands, roll into small balls and coat with breadcrumbs.", "Lightly brush with oil if desired. Place in a single layer.", "Air-fry at 180°C for 8–12 minutes, turning once, until golden and hot throughout. Cool before eating."], "5": ["Flatten the bread and press into silicone muffin cups.", "Spread 1 tbsp tomato sauce in each bread cup.", "Add corn, diced bell pepper and cheese.", "Air-fry at 170°C for 5–8 minutes until bread is crisp and cheese melts. Let cool."], "6": ["Unroll chilled puff pastry on a clean surface.", "Spread a thin layer of tomato sauce if using; scatter cheese and well-drained corn.", "Roll into a tight log. Cut into 8–10 slices.", "Lay flat with space between them. Air-fry at 170°C for 9–13 minutes until puffed, golden and pastry is cooked through. Cool."], "7": ["Wash the vegetables and grate the carrot.", "Whisk eggs, milk and salt; stir in cheese, carrot and corn.", "Pour into small silicone muffin cups, leaving a little space at the top.", "Air-fry at 160°C for 10–14 minutes until puffed and fully set in the middle. Cool."], "8": ["Cook, cool and finely chop the broccoli.", "Mix broccoli, cheese, egg, breadcrumbs and optional seasoning.", "Shape into small, slightly flattened nuggets with clean hands.", "Air-fry at 180°C for 10–14 minutes, turning halfway, until golden, firm and cooked through. Cool."], "9": ["Lay the bread slices on a clean board.", "Spread about 1 tbsp tomato sauce on each slice.", "Decorate with diced pepper and corn; sprinkle with cheese and oregano.", "Air-fry at 170°C for 5–7 minutes until cheese melts and bread crisps. Cool."], "10": ["Wash and slice sweet potato into thin wedges (easier than carving faces).", "Pat dry, then toss wedges with oil, salt and optional paprika.", "Arrange in a single layer in the air-fryer basket.", "Cook at 190°C for 12–18 minutes, turning halfway, until tender inside and browned outside."], "11": ["Wash all vegetables well. Cut the cucumber.", "Spread cream cheese over each tortilla.", "Add lettuce, grated carrot, cucumber and optional tomato in a thin layer.", "Roll each tortilla tightly into a log. Cut into bite-size pinwheels."], "12": ["Mix corn, egg, flour, cheese and milk into a thick spoonable batter.", "Warm a nonstick pan with a little oil over medium-low heat.", "Add small spoonfuls and cook about 2–3 minutes per side.", "Check the centres are fully cooked and golden. Cool before eating."], "13": ["Lay cheese on bread.", "Toast until cheese melts.", "Cool slightly; add cucumber ears and halved tomatoes for noses."], "14": ["Spread sauce on bagel halves.", "Add corn, peppers and cheese.", "Air-fry until cheese melts; cool."], "15": ["Cut zucchini into sticks.", "Dip in beaten egg, then crumbs mixed with Parmesan.", "Air-fry in one layer until golden and zucchini is tender."], "16": ["Spread cheese and vegetables over half of each tortilla.", "Fold closed and press lightly.", "Air-fry until crisp and cheese melts."], "17": ["Mash banana; stir in egg and oats.", "Cook small pancakes on a lightly oiled pan until fully set.", "Decorate cooled pancakes with cut strawberries."], "18": ["Wash fruit; peel and cut it into bite-size pieces.", "Arrange colors in rainbow order on a plate or blunt food-safe sticks."], "19": ["Core apples and cuts thick rings.", "Brush lightly with butter and sprinkle cinnamon.", "Air-fry until tender; let cool."], "20": ["Wash strawberries; blend fruit with yoghurt.", "Pour into popsicle moulds and freeze until solid."], "21": ["Wash and slice vegetables, quartering tomatoes.", "Spread cream cheese on crackers.", "Arrange vegetable pieces as flowers and leaves."], "22": ["Cook and cool the cauliflower.", "Mix all ingredients and shape small tots.", "Air-fry until firm, browned and egg fully cooked."], "23": ["With clean hands mix warm-but-not-hot freshly cooked rice and fully cooked vegetables.", "Shape into bite-size balls and eat promptly."], "24": ["Drain chickpeas and pat them dry.", "Toss with oil and paprika.", "Air-fry until crisp; cool and check texture before eating."], "25": ["Cut pastry into squares.", "Add chicken, cheese and sauce; fold and press edges.", "Air-fry until pastry is golden and cooked through and filling is hot."], "26": ["Fully cook nuggets according to package.", "Spread sauce on bread; add chopped nuggets, corn and cheese.", "Air-fry until hot and melted."], "27": ["Use clean utensils to place the raw chicken in a bowl; wash hands and surfaces thoroughly.", "Mix ingredients using clean utensils; shape small flattened nuggets.", "Air-fry until centres reach 74°C, checking with thermometer."], "28": ["Flatten bread into four silicone cups.", "Beat eggs and stir in cheese and corn.", "Fill the cups; air-fry until the eggs are completely set."], "29": ["Whisk eggs; stir in cheese and finely chopped vegetables.", "Pour into silicone moulds.", "Cook until egg centres are completely set."], "30": ["Cook scrambled eggs fully in a pan.", "Put eggs and cheese between bread slices.", "Use a star cutter; serve warm."], "31": ["Spread cream cheese on tortillas.", "Place banana and sliced strawberries inside; roll tightly.", "Cut into small spirals."], "32": ["Finely dice apple.", "Scatter apple and cinnamon over pastry; roll into a log.", "Slice and air-fry until pastry is cooked through."], "33": ["Wash and cut fruit.", "Layer yoghurt, fruit and oats in clear cups.", "Eat immediately or refrigerate."], "34": ["Mix cooled cooked potato with grated carrot, cheese and crumbs.", "Shape small tots.", "Air-fry until browned and heated through."], "35": ["Fill half of each tortilla with cheese, corn and spinach.", "Fold and press.", "Air-fry until crisp and cheese melts."], "36": ["Halve peppers and remove seeds.", "Fill with freshly cooked rice, corn and cheese.", "Air-fry until peppers are tender and filling hot."], "37": ["Wash vegetables.", "Spread cream cheese, add cooked chicken, carrot and lettuce.", "Roll tightly; slice and serve promptly."], "38": ["Whisk eggs and milk, add spinach and cheese.", "Pour into silicone cups.", "Air-fry until fully set."], "39": ["Mix all ingredients into thick batter.", "Cook small spoonfuls in a lightly oiled pan until centres are fully cooked."], "40": ["Cut the apple into thin slices and remove the core.", "Spread with seed or nut butter if allergy-safe.", "Add banana smiles and serve."], "41": ["Use clean utensils to place the raw chicken in a bowl; wash hands and surfaces thoroughly.", "Mix and shape small meatballs using clean utensils.", "Air-fry until centres reach 74°C on a food thermometer."], "42": ["Flatten bread.", "Cut strawberries; place inside and roll.", "Dip briefly in beaten egg and milk.", "Air-fry until bread is golden and egg coating completely cooked."], "43": ["Mix cooled potato, broccoli, cheese and crumbs.", "Shape into small stars or patties.", "Air-fry until golden and heated through."], "44": ["Whisk eggs and mix in vegetables, cheese and oregano.", "Fill silicone muffin cups.", "Cook until centres are completely set."], "45": ["Mash banana and mix with oats and cinnamon.", "Shape small flat cookies and add optional chips.", "Air-fry until firm and lightly browned."], "46": ["Cook nuggets according to the package instructions and chop them.", "Add nuggets, sauce and cheese to tortilla halves.", "Fold closed; air-fry until hot and crisp."], "47": ["Wash and prepare fruit.", "Blend everything until smooth.", "Pour into cups and enjoy cold."], "48": ["Mix carrot, egg, flour and cheese.", "Cook small spoonfuls on lightly oiled nonstick pan until browned and fully cooked."], "49": ["Wash and slice fruit.", "Layer yoghurt, banana, strawberries and granola in cups.", "Eat while crunchy."], "50": ["Cut bread into stars if desired.", "Spread sauce and add cooked chicken, corn and cheese.", "Air-fry until hot and melted."], "51": ["Scatter cheese, finely diced vegetables and a tiny pinch of chaat masala on bread.", "Air-fry until melted and toast is crisp."], "52": ["Cut paneer and pepper.", "Coat with yoghurt, mild spice and oil.", "Air-fry until heated through and lightly browned."], "53": ["Mix cooked potato, cheese and cumin.", "Spread between bread slices.", "Toast in a lightly buttered pan until both sides are golden."], "54": ["Spread sauce on bread.", "Top with paneer, corn and mozzarella.", "Air-fry until hot and cheese melts."], "55": ["Mix potato, peas, crumbs and cumin.", "Shape small patties.", "Pan-cook in a little oil until crisp and hot throughout."], "56": ["Mix potato, peas and cumin.", "Flatten bread lightly, add filling and roll tightly with damp edges.", "Brush with oil and air-fry until crisp."], "57": ["Mix cooled cooked vegetables with potato and crumbs.", "Shape hearts or stars.", "Air-fry until golden and heated through."], "58": ["Whisk besan, water and salt into pourable batter; stir in carrot and coriander.", "Cook small thin pancakes on both sides until completely cooked."], "59": ["Mix suji, yoghurt and water; rest 10 minutes.", "Add carrot, tomato and baking soda.", "Cook small thick pancakes covered on low-medium heat, flipping until cooked through."], "60": ["Soften onion and tomato in a pan with oil.", "Add beaten eggs and turmeric; stir until eggs are fully cooked.", "Add cheese and melt."], "61": ["Mash banana; whisk with flour, milk and cardamom into thick batter.", "Cook little pancakes in a lightly oiled pan until fully cooked."], "62": ["Rinse poha briefly and drain.", "Cook carrot with oil and a little water until tender; add peas, turmeric and poha.", "Heat through and finish with lemon."], "63": ["Mix coconut, condensed milk and cardamom into a moldable mixture.", "Roll into small balls and refrigerate until firm."], "64": ["Stir thick yoghurt, mango pulp and cardamom until smooth.", "Chill and serve in small bowls."], "65": ["Spread sauce on rotis; add capsicum, corn and cheese.", "Heat covered in a nonstick pan on low heat until cheese melts and base is crisp."]};
