const translationPattern=new RegExp('(?<![\\p{L}\\p{N}])(?:'+Object.keys(PT_TRANSLATIONS).sort((a,b)=>b.length-a.length).map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![\\p{L}\\p{N}])','gu');
function translateText(value,lang=state.language){
 const t=String(value??'');
 if(lang==='en-GB')return t.replace(/\bFiber\b/g,'Fibre').replace(/\bfiber\b/g,'fibre').replace(/\byogurt\b/g,'yoghurt').replace(/\bYogurt\b/g,'Yoghurt').replace(/\bmolds\b/g,'moulds').replace(/\bmold\b/g,'mould').replace(/\bmoldable\b/g,'mouldable').replace(/\bfavorites\b/g,'favourites').replace(/\bFavorites\b/g,'Favourites').replace(/\bfavorite\b/g,'favourite').replace(/\bFavorite\b/g,'Favourite').replace(/\bcolorful\b/g,'colourful').replace(/\bcolor\b/g,'colour').replace(/\bcolors\b/g,'colours').replace(/\bcenter\b/g,'centre').replace(/\bcenters\b/g,'centres').replace(/\bflavor\b/g,'flavour');
 if(PT_TRANSLATIONS[t])return PT_TRANSLATIONS[t];
 return t.replace(/1 of (\d+) equal servings/g,'1 de $1 porções iguais').replace(/I made (.+)!/g,(_,r)=>'Eu fiz '+translateText(r,'pt-BR')+'!').replace(translationPattern,m=>PT_TRANSLATIONS[m]);
}
const languageOriginals=new WeakMap();
function applyLanguage(root=document.body){
 document.documentElement.lang=state.language;document.title=state.language==='pt-BR'?'Cozinha mágica da Aaria':'Aaria’s Magical Kitchen';
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;
 while(n=walker.nextNode()){
  if(n.parentElement?.closest('script,style,#languageBar,[data-original-source]'))continue;
  let o=languageOriginals.get(n);if(o===undefined){o=n.textContent;languageOriginals.set(n,o)}
  const t=translateText(o);if(n.textContent!==t)n.textContent=t;
 }
 root.querySelectorAll('[aria-label],[placeholder],[alt],[title]').forEach(el=>{
  if(el.closest('#languageBar,[data-original-source]'))return;
  let saved=el._languageAttributes??={};for(const k of ['aria-label','placeholder','alt','title'])if(el.hasAttribute(k)){saved[k]??=el.getAttribute(k);if(k==='aria-label'&&el.classList.contains('v34-settings'))continue;const t=translateText(saved[k]);if(el.getAttribute(k)!==t)el.setAttribute(k,t)}
 });
 const select=document.querySelector('#languageSelect');if(select)select.value=state.language;
}
function recipeMatchesSearch(r,q){const fold=t=>String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const text=`${r.title} ${r.ingredients.join(' ')} ${r.method} ${PT_RECIPES[r.id].title} ${PT_RECIPES[r.id].ingredients.join(' ')}`;return fold(text).includes(fold(q));}
const MAIN_INGREDIENT_GROUPS=['Vegetables','Fruit','Grains & Bread','Eggs & Dairy','Chicken & Meat','Beans & Legumes','Other'];
function recipeMainIngredientGroup(r){const text=`${r.title||''} ${(r.ingredients||[]).slice(0,2).join(' ')}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(/chicken|turkey|beef|pork|meat|ham/.test(text))return 'Chicken & Meat';if(/chickpea|garbanzo|lentil|bean|hummus|falafel/.test(text))return 'Beans & Legumes';if(/banana|apple|mango|strawberr|blueberr|raspberr|fruit|pineapple|orange|grape|peach/.test(text))return 'Fruit';if(/vegetable|veggie|carrot|spinach|broccoli|cauliflower|zucchini|courgette|cucumber|tomato|potato|corn|sweetcorn|pea|bell pepper|capsicum|onion|avocado/.test(text))return 'Vegetables';if(/egg|milk|cheese|paneer|yogurt|yoghurt|cream|butter/.test(text))return 'Eggs & Dairy';if(/bread|rice|oat|flour|tortilla|pasta|roti|noodle|semolina|suji|poha|pastry|wrap/.test(text))return 'Grains & Bread';return 'Other'}
function recipeBrowseMatches(r){const air=applianceFilter==='All'||(applianceFilter==='Air fryer'&&/air[ -]?fryer/i.test(r.method||''));const main=mainFilter==='All'||recipeMainIngredientGroup(r)===mainFilter;return air&&main}
function recipeBrowseControls(){return `<div class="recipe-filter-controls"><label><span>Cooking method</span><select data-appliance-filter aria-label="Filter by cooking method"><option value="All" ${applianceFilter==='All'?'selected':''}>All methods</option><option value="Air fryer" ${applianceFilter==='Air fryer'?'selected':''}>Air fryer</option></select></label><label><span>Main ingredient</span><select data-main-filter aria-label="Filter by main ingredient"><option value="All" ${mainFilter==='All'?'selected':''}>All ingredients</option>${MAIN_INGREDIENT_GROUPS.map(c=>`<option value="${safe(c)}" ${mainFilter===c?'selected':''}>${safe(c)}</option>`).join('')}</select></label></div>`}

